-- Migration 056: Rewrite short stems into clinical vignettes + expand short explanations.
-- Covers ~268 questions flagged by audit (stem <50 chars or explanation <200 chars).
-- Run in Supabase SQL Editor. Safe to re-run (UPDATEs are idempotent by id).

-----------------------------------------------------------
-- PART 1: ARROW-STYLE AND VERY SHORT STEMS → clinical vignettes
-----------------------------------------------------------

-- Allergy: Anaphylaxis →
UPDATE akt_questions SET question = 'A 30-year-old woman develops lip swelling, wheeze, and hypotension within 10 minutes of eating a meal containing peanuts. What is the most appropriate immediate treatment?', explanation = 'Anaphylaxis requires immediate IM adrenaline (0.5 mg = 500 mcg, 1:1000) as first-line treatment. Do not delay. Antihistamines (chlorphenamine) and IV hydrocortisone are adjunctive but should not replace adrenaline. IV fluids for hypotension and nebulised salbutamol for bronchospasm are supportive. Call 999 and monitor. Repeat adrenaline at 5-minute intervals if no improvement.', updated_at = now() WHERE id = '8bacf47b-d4fa-4aa5-8ce0-c021adb3a192';

-- Dermatology: Suspected melanoma →
UPDATE akt_questions SET question = 'A 55-year-old man presents with a pigmented lesion on his back that has changed in size and colour over 3 months. What is the most appropriate next step?', explanation = 'A changing pigmented lesion is a red flag for melanoma and requires urgent 2-week wait referral to dermatology (NICE NG12). Use ABCDE criteria to support suspicion: Asymmetry, Border irregularity, Colour variation, Diameter >6 mm, Evolution. Do not biopsy or excise in primary care — specialist assessment is needed. Dermoscopy is performed in secondary care. Do not delay for photographs or monitoring.', updated_at = now() WHERE id = '4c40088b-8043-4afa-bd20-5376751f9897';

-- Dermatology: Melanoma sign:
UPDATE akt_questions SET question = 'A 48-year-old woman asks about warning signs of melanoma. Which feature of a pigmented lesion is most concerning?', explanation = 'The ABCDE criteria are used to assess pigmented lesions for melanoma: Asymmetry, Border irregularity, Colour variation (multiple colours within a lesion), Diameter >6 mm, and Evolution (any change in size, shape, or colour). Colour variation — particularly multiple colours (brown, black, red, white, blue) within a single lesion — is one of the most specific features. Any evolving lesion should prompt urgent 2-week wait referral to dermatology.', updated_at = now() WHERE id = '1ee5bd88-3e34-49e0-a854-1ceebd9a5081';

-- Dermatology: Mild eczema →
UPDATE akt_questions SET question = 'A 4-year-old child presents with mild eczema affecting the flexures. There is no infection. What is the most appropriate first-line management?', explanation = 'Mild eczema is managed with regular emollients as first-line treatment (NICE CKS). Apply emollients liberally and frequently (at least twice daily). For flares, add a mild topical corticosteroid (e.g. hydrocortisone 1%) for short courses. Moderate-potency steroids are for moderate eczema. Oral steroids and antibiotics are reserved for severe or infected eczema respectively. Soap substitutes should also be used.', updated_at = now() WHERE id = '4043a5db-8b61-47fe-a2d8-8d8b67ffe7aa';

-- Dermatology: Psoriasis first-line →
UPDATE akt_questions SET question = 'A 35-year-old man presents with well-demarcated, erythematous, scaly plaques on his elbows and knees. He has no joint symptoms. What is the most appropriate first-line treatment?', explanation = 'Chronic plaque psoriasis first-line treatment is topical therapy: vitamin D analogue (e.g. calcipotriol) and/or potent topical corticosteroid (e.g. betamethasone). Vitamin D analogues can be used long-term; topical steroids for short courses to control flares. Dithranol and coal tar are older options. Oral medications (methotrexate, ciclosporin) and biologics are for moderate-to-severe disease unresponsive to topical treatment. Refer to dermatology if topical therapy fails.', updated_at = now() WHERE id = '6caa5cb4-87a4-4b07-b4e5-af4309ca8a2b';

-- Dermatology: Shingles antivirals →
UPDATE akt_questions SET question = 'A 72-year-old woman presents with a painful, vesicular rash in a dermatomal distribution on her trunk. Symptoms started 48 hours ago. What is the most appropriate management?', explanation = 'Shingles (herpes zoster) antivirals — aciclovir 800 mg five times daily for 7 days (or valaciclovir 1 g TDS for 7 days) — should be started within 72 hours of rash onset for maximum benefit. They are especially important in patients aged >50 (higher risk of post-herpetic neuralgia), immunocompromised, or with ophthalmic involvement. After 72 hours, antivirals may still be considered if new vesicles are forming. Analgesia should be offered alongside.', updated_at = now() WHERE id = '77523a00-4f47-4566-b40a-22a3505cc4e8';

-- Dermatology: Cellulitis →
UPDATE akt_questions SET question = 'A 50-year-old man presents with an area of spreading erythema, warmth, and tenderness on his lower leg. He has a temperature of 37.8°C. What is the most appropriate first-line antibiotic?', explanation = 'Cellulitis first-line treatment is oral flucloxacillin 500 mg QDS for 5–7 days (NICE CKS). If penicillin allergic, use clarithromycin or doxycycline. If severe (systemic symptoms, extensive involvement, facial cellulitis), arrange hospital assessment for IV antibiotics. Elevate the affected limb. Mark the border of erythema and review in 48 hours. If no improvement, consider alternative diagnosis (e.g. venous eczema, DVT) or change antibiotic.', updated_at = now() WHERE id = '64b5e312-9e75-4a62-9ee6-27f68e1b10ec';

-- Dermatology: Moderate acne →
UPDATE akt_questions SET question = 'A 19-year-old woman has moderate acne with inflammatory papules and pustules that have not responded to 12 weeks of topical benzoyl peroxide and adapalene. What is the most appropriate next step?', explanation = 'For moderate acne not responding to topical combination therapy (benzoyl peroxide + retinoid), the next step is oral antibiotic: lymecycline 408 mg OD or doxycycline 100 mg OD for 3–6 months (NICE CKS). Combine with topical benzoyl peroxide (to reduce antibiotic resistance). If still ineffective or severe/scarring, refer to dermatology for isotretinoin. For women, co-cyprindiol (Dianette) or another combined oral contraceptive can be considered. Topical antibiotic alone is not recommended (resistance risk).', updated_at = now() WHERE id = '3644c159-0bdb-4acf-a3a1-50b4b1c2a862';

-- Endocrinology: Addisonian crisis →
UPDATE akt_questions SET question = 'A 52-year-old man with known Addison''s disease is brought to surgery feeling unwell with vomiting, abdominal pain, and confusion. BP is 85/50. What is the most likely biochemical finding?', explanation = 'Addisonian crisis (acute adrenal insufficiency) presents with hypotension, vomiting, abdominal pain, and confusion. Key biochemical features: hyperkalaemia (due to aldosterone deficiency), hyponatraemia (impaired free water excretion), hypoglycaemia. Hyperkalaemia is a hallmark finding. Urgent treatment: IV hydrocortisone 100 mg stat, IV 0.9% saline, and monitor electrolytes. Do not delay treatment for investigations.', updated_at = now() WHERE id = '94f0bfe5-a1e4-494c-9700-21e6785bfbd8';

-- Endocrinology: Obesity first-line →
UPDATE akt_questions SET question = 'A 42-year-old man with BMI 34 and no comorbidities asks about weight management. What is the most appropriate first-line intervention?', explanation = 'Obesity first-line treatment is lifestyle intervention: diet (calorie deficit, balanced diet), exercise (150 minutes moderate activity per week), and behavioural support (NICE CG189). If BMI ≥30 (or ≥27 with comorbidities) and lifestyle changes insufficient after 3–6 months, consider pharmacotherapy: orlistat (reduces fat absorption) or liraglutide/semaglutide (GLP-1 agonists, if BMI ≥35 or ≥30 with comorbidities). Bariatric surgery if BMI ≥40 or ≥35 with comorbidities and other treatments failed. Set realistic targets (5–10% initial loss).', updated_at = now() WHERE id = '131878f3-be27-4e91-a3d5-df2b136b949a';

-- Endocrinology: Most common cause of hyperthyroidism in the UK?
UPDATE akt_questions SET question = 'A 28-year-old woman presents with weight loss, tremor, and heat intolerance. TFTs show suppressed TSH and elevated free T4. What is the most likely underlying cause in the UK?', explanation = 'Graves'' disease is the most common cause of hyperthyroidism in the UK, accounting for 60–80% of cases, particularly in younger women. It is an autoimmune condition caused by TSH-receptor stimulating antibodies. Other causes include toxic multinodular goitre (more common in older adults), toxic adenoma, thyroiditis, and exogenous thyroid hormone. Graves'' may also cause ophthalmopathy and pretibial myxoedema. Check TSH-receptor antibodies to confirm.', updated_at = now() WHERE id = '5f5eb6be-77eb-45ec-a526-439a60ae7344';

-- Endocrinology: Red flag in thyroid eye disease?
UPDATE akt_questions SET question = 'A 40-year-old woman with known Graves'' disease presents with worsening proptosis and periorbital swelling. Which symptom would require the most urgent action?', explanation = 'Reduced visual acuity in thyroid eye disease suggests optic nerve compression (dysthyroid optic neuropathy) and requires urgent ophthalmology referral (same day). This is a sight-threatening emergency. Lid lag, proptosis, and grittiness are common in thyroid eye disease and should be monitored, but reduced visual acuity or colour vision loss indicates optic nerve involvement and demands emergency intervention (IV methylprednisolone or surgical decompression).', updated_at = now() WHERE id = '712c943f-9adc-4e6f-b295-cebdafcd0d83';

-- ENT: BPPV feature:
UPDATE akt_questions SET question = 'A 60-year-old woman describes brief episodes of vertigo triggered by rolling over in bed or looking up. Each episode lasts about 30 seconds. What is the most likely diagnosis?', explanation = 'Benign paroxysmal positional vertigo (BPPV) is the most common cause of vertigo. It is characterised by brief episodes (seconds to <1 minute) of vertigo triggered by specific head movements (rolling over, looking up, bending). Dix-Hallpike test confirms the diagnosis (positive nystagmus). Treatment is Epley manoeuvre. Ménière''s disease causes prolonged episodes with hearing loss and tinnitus. Vestibular neuritis causes prolonged continuous vertigo.', updated_at = now() WHERE id = '927e2b6e-641e-4e5f-a13f-6a8dd62dc1f5';

-- ENT: Sudden sensorineural hearing loss →
UPDATE akt_questions SET question = 'A 45-year-old man reports sudden hearing loss in his left ear that developed over a few hours. He has no pain, discharge, or trauma. What is the most appropriate next step?', explanation = 'Sudden sensorineural hearing loss (SSNHL) is an ENT emergency requiring urgent referral (same day or within 24 hours). It is defined as ≥30 dB loss in ≥3 contiguous frequencies over <72 hours. Causes include viral, vascular, autoimmune, and acoustic neuroma. Early treatment with oral steroids may improve outcomes; delayed treatment reduces recovery chances. Always exclude acoustic neuroma with MRI if no improvement. Do not delay referral for routine audiology.', updated_at = now() WHERE id = '03f77e5f-5364-44e6-8958-2d160460c583';

-- Evidence-Based Practice: Sensitivity measures:
UPDATE akt_questions SET question = 'A GP is evaluating a screening test for colorectal cancer. The test correctly identifies 95% of patients who have cancer. Which test property does this value describe?', explanation = 'Sensitivity (true positive rate) measures the ability of a test to correctly identify those WITH disease. It is calculated as: True Positives / (True Positives + False Negatives). A sensitivity of 95% means 95% of patients with cancer will test positive. High sensitivity means few false negatives, making the test good for ruling OUT disease (SnNout: Sensitive test, Negative result rules Out). Specificity measures the ability to identify those WITHOUT disease. PPV and NPV depend on prevalence.', updated_at = now() WHERE id = '9733ac7e-5f34-44a0-892c-f5afb2940a94';

-- Evidence-Based Practice: Specificity measures:
UPDATE akt_questions SET question = 'A GP is evaluating a confirmatory test for coeliac disease. The test correctly identifies 98% of patients who do NOT have coeliac disease. Which test property does this value describe?', explanation = 'Specificity (true negative rate) measures the ability to correctly identify those WITHOUT disease. It is calculated as: True Negatives / (True Negatives + False Positives). A specificity of 98% means 98% of patients without disease will test negative. High specificity means few false positives, making the test good for ruling IN disease (SpPin: Specific test, Positive result rules In). Sensitivity measures ability to identify those WITH disease. PPV and NPV are influenced by prevalence.', updated_at = now() WHERE id = '00d6b874-826a-41ac-8f93-08c50333fb1b';

-- Gastroenterology: PR bleeding + anaemia →
UPDATE akt_questions SET question = 'A 62-year-old man presents with a 4-week history of rectal bleeding and unexplained iron deficiency anaemia (Hb 105 g/L, ferritin 8 µg/L). What is the most appropriate next step?', explanation = 'PR bleeding combined with iron deficiency anaemia in an adult meets 2-week wait referral criteria for suspected colorectal cancer (NICE NG12). Arrange urgent referral — do not delay with faecal occult blood testing or routine referral. Other causes include haemorrhoids, diverticular disease, and IBD, but colorectal cancer must be excluded first. A full blood count will confirm iron deficiency anaemia. Colonoscopy is the gold standard investigation.', updated_at = now() WHERE id = '83863019-e176-4f84-8c29-1301805151f3';

-- Gastroenterology: Painless jaundice →
UPDATE akt_questions SET question = 'A 70-year-old man presents with a 2-week history of painless jaundice, dark urine, and pale stools. He has lost 5 kg in weight. What is the most likely diagnosis?', explanation = 'Painless obstructive jaundice with weight loss in an older patient suggests pancreatic head cancer (Courvoisier''s sign: painless jaundice + palpable gallbladder). Other causes: cholangiocarcinoma, ampullary carcinoma. This requires urgent 2-week wait referral and imaging (ultrasound first-line, then CT/MRI). Painful jaundice is more typical of gallstones. Always investigate jaundice urgently — do not delay. ERCP may be needed for biliary drainage.', updated_at = now() WHERE id = '06010a3f-ab73-4827-96c6-693a20f73fbd';

-- Gastroenterology: IBS feature:
UPDATE akt_questions SET question = 'A 32-year-old woman presents with 6 months of intermittent abdominal pain relieved by defecation, bloating, and alternating bowel habit. Blood tests and coeliac screen are normal. What is the most likely diagnosis?', explanation = 'Irritable bowel syndrome (IBS) is characterised by abdominal pain or discomfort associated with defecation or altered bowel habit, plus bloating. Diagnosis requires symptoms for ≥6 months and exclusion of red flags (NICE CG61). Red flags that would require further investigation include weight loss, rectal bleeding, fever, anaemia, family history of bowel/ovarian cancer, and onset after age 60. IBS is a diagnosis of exclusion with positive clinical features.', updated_at = now() WHERE id = 'f567131b-8a06-4453-82e3-fcfe0459e735';

-- Gastroenterology: Coeliac screen →
UPDATE akt_questions SET question = 'A 28-year-old woman presents with chronic diarrhoea, bloating, and iron deficiency anaemia. Coeliac disease is suspected. What is the most appropriate initial investigation?', explanation = 'Coeliac disease screening uses IgA tissue transglutaminase (tTG) antibodies as the first-line test (NICE NG20). Total IgA should be checked simultaneously, as IgA deficiency (present in ~2% of coeliac patients) causes false-negative tTG results — in which case IgG-based tests are used. The patient must be eating gluten-containing foods for at least 6 weeks before testing. Endoscopy with duodenal biopsy confirms the diagnosis. HLA-DQ2/DQ8 testing can help exclude coeliac disease.', updated_at = now() WHERE id = '45bb42ec-b416-4393-8ab4-b17dec9732f9';

-- Gastroenterology: NAFLD →
UPDATE akt_questions SET question = 'A 48-year-old man with BMI 32 and type 2 diabetes has incidentally raised ALT (65 U/L). Liver screen is otherwise normal and alcohol intake is minimal. Ultrasound shows fatty infiltration. What is the most appropriate management?', explanation = 'Non-alcoholic fatty liver disease (NAFLD) is managed primarily with weight loss and lifestyle modification: aim for 5–10% weight loss, regular exercise, and addressing metabolic risk factors (diabetes, dyslipidaemia, hypertension). No specific pharmacotherapy is licensed for NAFLD in the UK. Assess fibrosis risk using ELF or FIB-4 score — refer to hepatology if advanced fibrosis. Monitor LFTs and metabolic parameters. Avoid hepatotoxic medications and excess alcohol.', updated_at = now() WHERE id = '5c5822cd-51f5-470e-88e0-9d419809a00a';

-- Gastroenterology: Constipation red flag:
UPDATE akt_questions SET question = 'A 60-year-old man presents with a 6-week history of constipation and unintentional weight loss of 4 kg. What is the most appropriate next step?', explanation = 'Constipation with unexplained weight loss is a red flag combination that raises concern for colorectal malignancy and requires urgent investigation. In patients over 40 with a change in bowel habit and weight loss, arrange a 2-week wait referral. Other red flags include rectal bleeding, iron deficiency anaemia, and abdominal mass. Duration of constipation alone, age, or lifestyle factors are less concerning in isolation. Do not attribute symptoms to benign causes without excluding serious pathology.', updated_at = now() WHERE id = '35811502-62dd-488b-bf5c-2652b4e03a07';

-- Gastroenterology: Uncomplicated diverticular disease →
UPDATE akt_questions SET question = 'A 58-year-old woman is found to have diverticulosis on colonoscopy performed for screening. She has occasional mild left-sided abdominal discomfort but no fever, bleeding, or signs of infection. What is the most appropriate management?', explanation = 'Uncomplicated diverticular disease (diverticulosis with mild symptoms) is managed with dietary advice: increase fibre intake gradually and maintain adequate fluid intake (NICE CKS). Bulk-forming laxatives may help if dietary fibre alone is insufficient. Antibiotics are not indicated — they are reserved for acute diverticulitis (with fever, raised inflammatory markers, localised peritonism). Surgery is for complications such as perforation, abscess, fistula, or recurrent diverticulitis.', updated_at = now() WHERE id = '58296513-9aa3-4bc3-adcb-7f83e9738e5e';

-- Gastroenterology: Peritonitis →
UPDATE akt_questions SET question = 'A 65-year-old man presents with severe generalised abdominal pain. On examination there is board-like rigidity, guarding, and absent bowel sounds. HR 110, BP 90/60. What is the most appropriate immediate action?', explanation = 'Peritonitis (inflammation of the peritoneum, often from perforation) is a surgical emergency requiring urgent hospital admission and likely emergency laparotomy. Signs: severe pain, guarding, board-like rigidity, rebound tenderness, absent bowel sounds, fever, tachycardia, and hypotension. Causes include perforated peptic ulcer, perforated appendicitis, perforated diverticulitis, and ischaemic bowel. Do not delay transfer — arrange immediate 999 or blue-light transfer. Initiate IV access and fluids if possible.', updated_at = now() WHERE id = 'dbc54755-1a3e-4ccf-85d3-61e897dd39c5';

-- Geriatrics: Delirium risk factor:
UPDATE akt_questions SET question = 'An 82-year-old woman is admitted to hospital with a UTI. She becomes acutely confused overnight. She takes 8 regular medications. Which of her characteristics is the strongest predisposing risk factor for developing delirium?', explanation = 'Polypharmacy (≥5 medications) is a major modifiable risk factor for delirium, alongside older age (>65), pre-existing cognitive impairment or dementia, current illness (especially infection), sensory impairment, and dehydration. Acute confusion (delirium) is a medical emergency — identify and treat the precipitant (e.g. infection, medication, metabolic disturbance). Use 4AT or CAM for screening. Review and rationalise medications. Maintain orientation, hydration, and nutrition.', updated_at = now() WHERE id = '103f2b0b-29d1-44c5-b026-64b5df69a854';

-- Haematology: DVT duration:
UPDATE akt_questions SET question = 'A 45-year-old woman developed a DVT 6 weeks after a long-haul flight. She is on rivaroxaban. How long should anticoagulation continue?', explanation = 'For a provoked DVT (identifiable transient risk factor such as surgery, immobilisation, long-haul travel, or pregnancy), anticoagulation is typically for 3 months (NICE NG158). Unprovoked DVT requires 3–6 months with assessment for extended treatment based on bleeding risk vs recurrence risk. Cancer-associated DVT is treated for the duration of active cancer. Recurrent DVT or confirmed thrombophilia may warrant extended or lifelong anticoagulation. DOACs (rivaroxaban, apixaban) are preferred over warfarin.', updated_at = now() WHERE id = '0a1894c1-583e-4396-8497-4e117c6a357a';

-- Haematology: Transfusion threshold:
UPDATE akt_questions SET question = 'A 70-year-old man with no cardiac history has a haemoglobin of 68 g/L following an upper GI bleed that has now stopped. He is haemodynamically stable. What is the transfusion threshold?', explanation = 'Blood transfusion threshold is typically Hb <70 g/L for haemodynamically stable patients without active cardiac disease (NICE NG24). For patients with acute coronary syndrome or symptomatic cardiac disease, a threshold of <80 g/L is used. Aim for a target Hb of 70–90 g/L. Transfuse one unit at a time and reassess. Higher thresholds may be appropriate in massive haemorrhage or ongoing bleeding. Restrictive transfusion strategies reduce complications compared to liberal approaches.', updated_at = now() WHERE id = '9513ff78-9d1c-400f-98ef-9627cdb3e8e4';

-- Haematology: Bleeding risk score:
UPDATE akt_questions SET question = 'A 75-year-old man with atrial fibrillation is being considered for anticoagulation. Which scoring system is used to assess his bleeding risk?', explanation = 'HAS-BLED score assesses bleeding risk in patients on anticoagulation (Hypertension, Abnormal liver/renal function, Stroke, Bleeding tendency, Labile INR, Elderly >65, Drugs/alcohol). A high HAS-BLED score identifies modifiable risk factors to address but does not contraindicate anticoagulation. CHA₂DS₂-VASc assesses stroke risk in AF. Wells score assesses DVT/PE probability. CURB-65 assesses pneumonia severity. QRISK3 assesses 10-year cardiovascular risk.', updated_at = now() WHERE id = '0dc4f62f-084f-47b6-8be5-27ca7438951a';

-- Haematology: Low MCV →
UPDATE akt_questions SET question = 'A 35-year-old woman presents with fatigue. Her FBC shows Hb 95 g/L and MCV 68 fL. What is the most common cause of this blood picture?', explanation = 'Low MCV (<80 fL) indicates microcytic anaemia. Iron deficiency is the most common cause — check ferritin (low ferritin is diagnostic). Other causes: thalassaemia trait (usually mild anaemia, high RBC count, ethnic background), anaemia of chronic disease (usually normocytic but can be microcytic), and sideroblastic anaemia (rare). Iron deficiency requires investigation of the underlying cause: in premenopausal women, heavy menstrual bleeding is common; in men or postmenopausal women, GI blood loss must be excluded.', updated_at = now() WHERE id = '196bc88a-6e19-4ec4-9c50-5bbddaa19c46';

-- Infectious Diseases: FUO first step:
UPDATE akt_questions SET question = 'A 55-year-old man has had a fever >38.3°C for 3 weeks with no diagnosis despite initial investigations. What is the most appropriate first step in evaluating fever of unknown origin?', explanation = 'Fever of unknown origin (FUO) investigation starts with a thorough, detailed history and examination to guide further targeted tests (NICE CKS). Key areas: travel history, occupational exposure, animal contacts, drug history, sexual history, family history, and review of systems. Blind ordering of investigations is inefficient. Blood cultures, inflammatory markers, and imaging (CXR, CT) come after clinical assessment has generated a differential. The three main categories are infection, malignancy, and autoimmune conditions.', updated_at = now() WHERE id = '83b9c32f-34e4-490c-951c-70e03e037fb8';

-- Infectious Diseases: Sepsis sign:
UPDATE akt_questions SET question = 'A 68-year-old woman with a UTI is brought to the practice by her family. She is confused, tachycardic (HR 105), and has a temperature of 38.5°C. Which assessment tool should be used to stratify her risk?', explanation = 'NEWS2 (National Early Warning Score 2) is used in the NHS to assess and stratify acutely unwell patients, including those with suspected sepsis. It scores physiological parameters (respiratory rate, SpO2, systolic BP, pulse, consciousness, temperature). A high NEWS2 score triggers escalation. Sepsis-6 bundle (give oxygen, take blood cultures, give IV antibiotics, give IV fluids, measure lactate, measure urine output) should be initiated if sepsis is suspected. Red flags: altered mental state, systolic BP <90, lactate >2, mottled skin.', updated_at = now() WHERE id = 'ad3070c0-234f-43e8-96b5-1fefb25ecc4f';

-- Musculoskeletal: PMR feature:
UPDATE akt_questions SET question = 'A 72-year-old woman presents with bilateral shoulder and hip girdle pain and stiffness for 4 weeks. Morning stiffness lasts over 1 hour. ESR is 55 mm/h. What is the most likely diagnosis?', explanation = 'Polymyalgia rheumatica (PMR) is characterised by bilateral shoulder and hip girdle pain and stiffness, morning stiffness lasting >45 minutes, raised inflammatory markers (ESR/CRP), and age >50. Diagnosis is clinical. Unilateral or asymmetric pain is less typical. Normal ESR/CRP makes PMR unlikely. Rapid response to low-dose prednisolone (15 mg daily) is characteristic and supports the diagnosis. Always exclude giant cell arteritis (headache, visual symptoms, jaw claudication) which can coexist with PMR.', updated_at = now() WHERE id = 'b19824a8-3631-49b2-88cf-95ff4ee61105';

-- Musculoskeletal: PMR treatment:
UPDATE akt_questions SET question = 'A 70-year-old man has been diagnosed with polymyalgia rheumatica. He has no features of giant cell arteritis. What is the most appropriate initial treatment?', explanation = 'PMR is treated with prednisolone, typically starting at 15 mg daily (NICE CKS/BSR guidelines). A dramatic response within 1–2 weeks supports the diagnosis. Taper gradually over 12–18 months based on symptoms and inflammatory markers. NSAIDs alone are insufficient. Methotrexate may be used as a steroid-sparing agent in relapsing disease. Proton pump inhibitor and bone protection (calcium, vitamin D, and consider bisphosphonate) should be co-prescribed with long-term steroids.', updated_at = now() WHERE id = 'df805e97-47d2-4380-bc58-4578447f670b';

-- Musculoskeletal: Painful arc suggests:
UPDATE akt_questions SET question = 'A 50-year-old man presents with shoulder pain. On examination, he has pain during abduction between 60° and 120° but no pain at rest or at full elevation. What is the most likely diagnosis?', explanation = 'A painful arc (pain between 60–120° of shoulder abduction) is the hallmark of rotator cuff tendinopathy or subacromial impingement. Pain at this range occurs because the supraspinatus tendon is compressed under the acromion. Frozen shoulder (adhesive capsulitis) causes global restriction of movement in all directions. Glenohumeral osteoarthritis causes pain at the extremes of range. Cervical radiculopathy causes pain in a dermatomal pattern with possible neurological signs.', updated_at = now() WHERE id = '6fce5ad0-a40f-4dbe-af79-b605f2a81ff2';

-- Neurology: Bell's palsy <72h treatment:
UPDATE akt_questions SET question = 'A 38-year-old woman presents with sudden-onset unilateral facial weakness affecting the forehead, eye, and mouth. She noticed it this morning (12 hours ago). Ear examination is normal. What is the most appropriate treatment?', explanation = 'Bell''s palsy (idiopathic lower motor neurone facial nerve palsy) should be treated with prednisolone (e.g. 50 mg OD for 10 days) started within 72 hours of onset (NICE CKS). Early steroid treatment improves recovery rates. Antivirals (e.g. aciclovir) may be added but evidence is less clear; steroids are the priority. Eye protection (lubricants, taping at night) is important to prevent corneal damage. If no recovery by 3 months or atypical features, refer to ENT or neurology.', updated_at = now() WHERE id = '34c1b475-924c-4560-a769-b2f11a46269d';

-- Neurology: Essential dementia workup:
UPDATE akt_questions SET question = 'A 76-year-old man presents with progressive memory loss over 6 months. His wife reports he is repeating himself and has got lost twice. What initial investigations should be arranged to exclude reversible causes?', explanation = 'Essential dementia workup includes blood tests to exclude reversible causes: FBC, U&Es, LFTs, calcium, TFTs (hypothyroidism), B12 and folate, glucose/HbA1c. These are done before or alongside cognitive assessment (e.g. MMSE, MoCA, or ACE-III). Brain imaging (MRI or CT) is usually arranged as part of specialist assessment. Imaging helps exclude structural causes (tumour, subdural, hydrocephalus) and may show patterns suggestive of specific dementia subtypes. Refer to memory clinic for formal assessment.', updated_at = now() WHERE id = '19327421-b262-4651-88f8-35485a3330ef';

-- Neurology: Symptom of TIA:
UPDATE akt_questions SET question = 'A 68-year-old man experienced sudden-onset right arm weakness and slurred speech lasting 20 minutes, which has now fully resolved. What is the most likely diagnosis?', explanation = 'A TIA (transient ischaemic attack) presents with sudden-onset focal neurological symptoms (weakness, speech disturbance, visual loss) that resolve completely within 24 hours, usually within minutes to hours. Gradual onset or non-focal symptoms (e.g. generalised dizziness, confusion alone) are not typical of TIA and suggest alternative diagnoses. Urgent assessment is needed: aspirin 300 mg immediately, referral to TIA clinic within 24 hours (or same day if high-risk). ABCD2 score helps stratify risk.', updated_at = now() WHERE id = 'ec5da949-0972-4de8-829c-3be9aa7ec124';

-- Neurology: Core Parkinson's feature:
UPDATE akt_questions SET question = 'A 65-year-old man presents with a resting tremor in his right hand, difficulty initiating movement, and a shuffling gait. Which of these is the cardinal motor feature required for a diagnosis of Parkinson''s disease?', explanation = 'Bradykinesia (slowness of movement with progressive reduction in speed and amplitude of repetitive actions) is the cardinal feature of Parkinson''s disease — diagnosis requires bradykinesia plus at least one of: rest tremor, rigidity. A classic "pill-rolling" rest tremor is common. Spasticity, hyperreflexia, and extensor plantar responses are upper motor neurone signs, not features of Parkinson''s. Intention tremor suggests cerebellar pathology. Refer to specialist (neurology or geriatrics) for diagnosis.', updated_at = now() WHERE id = '2f28310f-9702-47da-a6ca-077a985dce81';

-- Renal: Urology red flag:
UPDATE akt_questions SET question = 'A 58-year-old man presents with a single episode of painless visible haematuria. He has no urinary symptoms, infection, or trauma. What is the most appropriate next step?', explanation = 'Painless visible (macroscopic) haematuria is a red flag requiring urgent 2-week wait referral for suspected urological malignancy (bladder or renal cancer, NICE NG12). Do not attribute to benign causes without investigation. Investigations include cystoscopy and upper tract imaging (CT urogram). In patients >45 with unexplained non-visible haematuria, consider referral. UTI-associated haematuria should still be investigated once infection has resolved. LUTS, nocturia, and frequency alone are not red flags but should be assessed.', updated_at = now() WHERE id = 'a5d712fc-d678-42db-a9fa-5ef14507c148';

-- Renal: Hyponatraemia cause:
UPDATE akt_questions SET question = 'A 72-year-old woman on bendroflumethiazide presents with confusion and lethargy. Bloods show Na 124 mmol/L. What is the most likely cause of her hyponatraemia?', explanation = 'Thiazide diuretics (e.g. bendroflumethiazide) are one of the most common drug causes of hyponatraemia, particularly in elderly women. They impair the kidney''s ability to excrete free water. Other causes: SIADH (malignancy, drugs, CNS disease), heart failure, liver cirrhosis, Addison''s disease, and excess fluid intake. Review and stop the thiazide, recheck Na. Manage based on severity and acuity: mild/chronic hyponatraemia is corrected slowly (risk of osmotic demyelination with rapid correction).', updated_at = now() WHERE id = '0eda8100-4f51-416b-b1a4-f446629a9bf7';

-- Renal: AKI diagnosis includes:
UPDATE akt_questions SET question = 'A 70-year-old man presents with reduced urine output. His creatinine today is 180 µmol/L; it was 95 µmol/L one week ago. Which criteria confirms an AKI diagnosis?', explanation = 'AKI is diagnosed by a rise in serum creatinine ≥26 µmol/L within 48 hours, or a ≥50% (1.5×) rise from baseline known or presumed within the past 7 days, or urine output <0.5 mL/kg/hour for >6 hours (NICE CKS). His creatinine has risen by 89% from baseline in 7 days, confirming AKI. eGFR <60 alone indicates CKD, not AKI. Proteinuria and haematuria are not diagnostic of AKI but may indicate the underlying cause. Stage the AKI and identify the cause (pre-renal, intrinsic, post-renal).', updated_at = now() WHERE id = 'a74db7df-b21c-45a9-a186-5cf131fcdb52';

-- Renal: ED first-line treatment:
UPDATE akt_questions SET question = 'A 55-year-old man with type 2 diabetes presents with erectile dysfunction. He has no cardiac symptoms and is on no nitrates. What is the most appropriate first-line treatment?', explanation = 'PDE-5 inhibitors (sildenafil, tadalafil) are first-line for erectile dysfunction (NICE CKS). They are contraindicated with nitrates due to severe hypotension risk. Testosterone replacement is only appropriate if hypogonadism is confirmed (low morning testosterone on two occasions). Vacuum devices and intracavernosal injections are alternatives if PDE-5 inhibitors are contraindicated or ineffective. Surgical implants are last resort. Address modifiable risk factors: diabetes control, cardiovascular risk, smoking, alcohol.', updated_at = now() WHERE id = '26eddd71-0a2a-426f-90d2-655a6978a4e6';

-- Respiratory: Poor asthma control →
UPDATE akt_questions SET question = 'A 28-year-old woman with asthma reports using her salbutamol inhaler 4 times per week and waking twice at night with wheeze. She is on beclomethasone 200 mcg BD. Which feature most clearly indicates poor asthma control?', explanation = 'Night-time waking with asthma symptoms is a marker of poor control (BTS/SIGN, NICE). Other indicators include: SABA use >3 times per week, limitation of daily activities, reduced peak flow, and exacerbations. Night symptoms are particularly significant as they indicate ongoing airway inflammation. Management: check inhaler technique and adherence first. If these are adequate, step up treatment (add LABA or increase ICS dose). Review regularly.', updated_at = now() WHERE id = '98966a1c-b9b0-4ddc-944d-89b81fd2276c';

-- Respiratory: D-dimer →
UPDATE akt_questions SET question = 'A 35-year-old woman presents with pleuritic chest pain and mild breathlessness after a long car journey. Her Wells score for PE is 1 (low probability). What is the most appropriate next investigation?', explanation = 'D-dimer is a fibrin degradation product used to exclude DVT/PE in patients with low pre-test probability (low Wells score). If D-dimer is negative and Wells score is low, PE is effectively excluded without imaging. If D-dimer is positive or Wells score is high (≥5), CT pulmonary angiogram is needed. D-dimer is elevated in many conditions (infection, pregnancy, malignancy, recent surgery, inflammation) so it is not useful as a diagnostic test — only to exclude in low-probability patients.', updated_at = now() WHERE id = 'b963e147-8db3-4ecf-bb16-47e834fae7a6';

-- Mental Health: Substance misuse →
UPDATE akt_questions SET question = 'A 30-year-old man attends for a routine appointment. You notice signs of intravenous drug use. He admits to using heroin. What is the most appropriate initial management approach in primary care?', explanation = 'Substance misuse is managed with a brief intervention (motivational interviewing approach), harm reduction advice (needle exchange, naloxone provision), and referral to specialist addiction services. Direct criticism, punishment, or ignoring the issue are not appropriate. Medication (e.g. methadone, buprenorphine for opioid substitution) is part of specialist treatment. Screen for blood-borne viruses (HIV, hepatitis B and C). Assess mental health and social circumstances. A non-judgemental, supportive approach improves engagement.', updated_at = now() WHERE id = '90608ebb-09a1-43f7-9b2f-1e3f853a9a77';

-- Prescribing: Smoking cessation →
UPDATE akt_questions SET question = 'A 50-year-old man who smokes 20 cigarettes per day asks for help to stop smoking. He has tried willpower alone before without success. What is the most effective approach?', explanation = 'Smoking cessation is most effective with combination therapy: pharmacotherapy (NRT — patches + fast-acting form, or varenicline, or bupropion) PLUS behavioural support (NICE CKS). Varenicline is the most effective single agent for smoking cessation. Behavioural support (group or individual) significantly increases quit rates. Advice alone is less effective but still worthwhile (brief intervention increases quit rates by 1–3%). E-cigarettes are not licensed medicines but may be discussed. Refer to local stop-smoking service.', updated_at = now() WHERE id = '68f5ba2e-2bfd-4a72-b0f4-f4a2e7cec997';

-- Renal: Testicular lump management:
UPDATE akt_questions SET question = 'A 28-year-old man presents with a painless, hard lump on his right testis found incidentally during self-examination. What is the most appropriate next step?', explanation = 'A painless testicular lump in a young man should be considered testicular cancer until proven otherwise. Arrange urgent ultrasound (within 2 weeks, 2-week wait referral pathway). Do not delay or treat empirically with antibiotics. Testicular cancer is the most common cancer in men aged 15–45. Tumour markers (AFP, beta-hCG, LDH) can support staging. Prognosis is excellent with early detection and treatment. Advise regular self-examination.', updated_at = now() WHERE id = '6c9e373f-73c2-4d57-ba5a-e844c33937d3';

-- Women's Health: Vasomotor menopause symptoms:
UPDATE akt_questions SET question = 'A 52-year-old woman presents with frequent hot flushes and night sweats that significantly affect her sleep and daily life. She has no contraindications to HRT. What is the most appropriate first-line treatment?', explanation = 'HRT (hormone replacement therapy) is first-line for moderate-to-severe vasomotor symptoms (hot flushes, night sweats) if there are no contraindications (NICE NG23). Offer oestrogen + progestogen if uterus intact; oestrogen alone if hysterectomy. SSRIs (e.g. fluoxetine), SNRIs (venlafaxine), gabapentin, and clonidine are alternatives for women who cannot or prefer not to take HRT. Lifestyle measures alone (exercise, cool environment) are often insufficient for severe symptoms.', updated_at = now() WHERE id = '62645257-baf3-47ef-9bc7-c5860ab33dba';

-- Women's Health: Breastfeeding mastitis management:
UPDATE akt_questions SET question = 'A 30-year-old breastfeeding woman presents with a painful, red, swollen area on her left breast. She has a temperature of 38.2°C and has been unwell for 24 hours. What is the most appropriate management?', explanation = 'Mastitis management: continue breastfeeding (important for drainage; stopping breastfeeding worsens the condition). If systemic symptoms (fever, feeling unwell) or not improving after 12–24 hours of effective milk removal, prescribe flucloxacillin (or erythromycin if penicillin-allergic) for 10–14 days. Advise warm compresses before feeds and cold compresses after. If a fluctuant mass develops (breast abscess), refer for ultrasound-guided aspiration or incision and drainage.', updated_at = now() WHERE id = 'fac0c889-c078-4286-8027-179924ec4747';

-- Women's Health: Smoking pregnancy best advice:
UPDATE akt_questions SET question = 'A 26-year-old woman who is 12 weeks pregnant smokes 10 cigarettes per day. She wants to quit. What is the most appropriate advice regarding nicotine replacement therapy?', explanation = 'NRT (nicotine replacement therapy) is acceptable in pregnancy and is safer than continued smoking (NICE PH26). It should be used if the woman cannot quit unaided. Intermittent-use NRT (gum, lozenges, inhalers) is preferred; patches can be used but should be removed at night. Going "cold turkey" may be too difficult and relapse rates are high. E-cigarettes are not recommended in pregnancy due to limited safety data. Refer to specialist stop-smoking service with pregnancy expertise.', updated_at = now() WHERE id = '8162b06b-aaed-46fa-8881-c817dc717d8f';

-----------------------------------------------------------
-- PART 2: EXPAND SHORT EXPLANATIONS (stem is okay, explanation <200 chars)
-----------------------------------------------------------

-- Cardiovascular: BP threshold
UPDATE akt_questions SET explanation = 'NICE NG136: Diagnose hypertension if clinic BP ≥140/90 confirmed by ABPM ≥135/85. Treat if stage 1 (140/90–159/99) AND 10-year CVD risk ≥10% (or target organ damage, diabetes, renal disease); or if stage 2 (≥160/100) regardless of risk. Calculate QRISK3 to assess cardiovascular risk. Lifestyle advice for all: reduce salt, increase exercise, moderate alcohol, healthy diet. BP 150/92 is stage 1 — assess CVD risk before starting medication.', updated_at = now() WHERE id = 'c61d6341-41a3-4bbf-922a-516f62afbe4c';

-- Cardiovascular: Next medication for stable angina
UPDATE akt_questions SET explanation = 'Beta-blockers (e.g. bisoprolol, atenolol) or calcium channel blockers (e.g. amlodipine, diltiazem) are first-line for symptom relief in stable angina (NICE CG126). If one is insufficient, the other class can be added. If already on aspirin and statin for secondary prevention, the next symptomatic treatment is a beta-blocker. Long-acting nitrates (isosorbide mononitrate) are second-line or add-on. GTN spray is for acute episodes. Ivabradine, nicorandil, and ranolazine are third-line options.', updated_at = now() WHERE id = '7257994e-d66f-40ba-a057-7a17be76d1eb';

-- Cardiovascular: ABPM confirms hypertension
UPDATE akt_questions SET explanation = 'NICE NG136: ABPM daytime average ≥135/85 mmHg confirms a diagnosis of hypertension. This threshold is lower than clinic BP (≥140/90) because ABPM eliminates white-coat effect. ABPM is the gold standard for confirming hypertension. Home BP monitoring (HBPM) can be used if ABPM not tolerated; the same threshold (≥135/85) applies. Stage 1 hypertension = clinic 140/90–159/99 (ABPM 135/85–149/94). Stage 2 = clinic ≥160/100 (ABPM ≥150/95).', updated_at = now() WHERE id = '56d16725-7b15-420f-b59c-cf3933e7cb1a';

-- Cardiovascular: Warfarin target INR
UPDATE akt_questions SET explanation = 'For atrial fibrillation, the target INR range is 2.0–3.0 when warfarin is used for stroke prevention. For mechanical heart valves, the target is higher (2.5–3.5 or higher depending on valve type and position). Lower targets are not standard for AF. INR should be monitored regularly; more frequently when initiating or adjusting dose. DOACs (apixaban, rivaroxaban) are now preferred over warfarin for AF anticoagulation and do not require INR monitoring (NICE NG196).', updated_at = now() WHERE id = 'feb7dc50-df41-4e54-b383-bd20c5717d6a';

-- Endocrinology: Hypothyroidism diagnosis
UPDATE akt_questions SET explanation = 'Elevated TSH with low free T4 indicates primary hypothyroidism (thyroid gland failure). TSH >10 mU/L with symptoms (fatigue, weight gain, cold intolerance, constipation) warrants treatment with levothyroxine. Subclinical hypothyroidism has elevated TSH but normal free T4 — treatment is considered if TSH >10 or if symptomatic. Secondary (central) hypothyroidism shows low TSH AND low T4 (pituitary failure). Start levothyroxine at 25–50 mcg and titrate based on TSH.', updated_at = now() WHERE id = 'd94e114e-196d-4ef2-877c-dc5470380658';

-- Endocrinology: HbA1c target diabetes
UPDATE akt_questions SET explanation = 'NICE NG28: Target HbA1c for type 2 diabetes is ≤48 mmol/mol (6.5%) for patients on a single drug not associated with hypoglycaemia (e.g. metformin alone), or ≤53 mmol/mol (7.0%) for patients on drugs that cause hypoglycaemia (e.g. sulphonylureas, insulin). Individualise targets: may be higher for frail, elderly, or patients at high hypoglycaemia risk. Current HbA1c of 58 mmol/mol is above target — review adherence, lifestyle, and consider adding a second agent.', updated_at = now() WHERE id = '8d098d4c-1fc6-46aa-b469-14cf94b1d548';

-- Endocrinology: Primary hypothyroidism findings
UPDATE akt_questions SET explanation = 'Primary hypothyroidism shows high TSH and low free T4. The thyroid gland is failing, so the pituitary increases TSH production in response. Low TSH with low T4 suggests secondary (central) hypothyroidism — a pituitary or hypothalamic cause. High TSH with normal T4 is subclinical hypothyroidism. Graves'' disease (hyperthyroidism) shows low TSH with high T4. Hashimoto''s thyroiditis is the most common cause of primary hypothyroidism in the UK.', updated_at = now() WHERE id = '867cd56c-389c-498d-b852-fb6434bd9b73';

-- Gastroenterology: Dyspepsia first-line
UPDATE akt_questions SET explanation = 'NICE CG184: For uninvestigated dyspepsia without alarm features (dysphagia, weight loss, GI bleeding, anaemia, persistent vomiting, epigastric mass, age ≥55 with new symptoms), offer a 4-week trial of full-dose PPI (e.g. omeprazole 20 mg OD). If symptoms persist after PPI, test for H. pylori (urea breath test or stool antigen). If H. pylori positive, give eradication therapy. Endoscopy is reserved for alarm features, age ≥55 with new symptoms, or persistent symptoms despite treatment.', updated_at = now() WHERE id = 'f48ff1b8-6b06-4d37-9e8c-609d05b6d850';

-- Gastroenterology: Mesenteric ischaemia
UPDATE akt_questions SET explanation = 'Sudden severe abdominal pain in a patient with AF suggests acute mesenteric ischaemia due to embolic occlusion of the superior mesenteric artery. This is a surgical emergency. The classic presentation is "pain out of proportion to examination" — severe pain with initially soft abdomen. AF is a major risk factor for arterial embolism. Peritonism develops later as bowel becomes ischaemic or infarcted. Requires urgent CT angiography and surgical assessment. Mortality is high if diagnosis is delayed.', updated_at = now() WHERE id = 'a9449daf-ed21-41c8-9241-8256577818ae';

-- Gastroenterology: IBS diarrhoea treatment
UPDATE akt_questions SET explanation = 'NICE CG61: For IBS with predominant diarrhoea, first-line is dietary advice (regular meals, adequate fluids, limit caffeine/alcohol). A low FODMAP diet (supervised by a dietitian) is effective but is not always the first step. Loperamide is first-line pharmacotherapy for diarrhoea-predominant IBS. Mebeverine or hyoscine can help cramps. Linaclotide is specifically for IBS with constipation (IBS-C). Psychological therapies (CBT, gut-directed hypnotherapy) are for refractory IBS.', updated_at = now() WHERE id = '2bb6bb92-f656-4457-ba32-358d1d6836dd';

-- Haematology: Macrocytic anaemia workup
UPDATE akt_questions SET explanation = 'Macrocytic anaemia (MCV >100 fL) requires B12 and folate levels as first-line investigations. B12 deficiency causes neurological features; folate deficiency does not. Other causes of macrocytosis: alcohol excess, hypothyroidism, medications (methotrexate, azathioprine, anticonvulsants), liver disease, myelodysplasia, and reticulocytosis. Check thyroid function, liver function, and reticulocyte count. A blood film may show hypersegmented neutrophils (B12/folate deficiency) or target cells (liver disease).', updated_at = now() WHERE id = '1f3df59d-7a07-4e90-8fb6-dda07e5ebf5c';

-- Infectious Diseases: Febrile child non-blanching rash
UPDATE akt_questions SET explanation = 'A febrile child with a non-blanching rash (petechiae or purpura) must be treated as meningococcal disease until proven otherwise — this is a medical emergency. Give IM benzylpenicillin (if available and no anaphylaxis history) and call 999 immediately. Do not delay transfer for investigations. Meningococcal septicaemia can progress rapidly. Other causes of non-blanching rash include ITP and HSP, but meningococcal disease must be excluded first.', updated_at = now() WHERE id = '8ee70979-6461-4d66-adab-102cc52d9dff';

-- Mental Health: Panic disorder first-line
UPDATE akt_questions SET explanation = 'SSRIs (e.g. sertraline, fluoxetine) are first-line pharmacotherapy for panic disorder (NICE CG113). CBT is also effective and may be offered first or alongside medication. Benzodiazepines should be avoided due to dependence risk and are not recommended for panic disorder. Beta-blockers (e.g. propranolol) may help physical symptoms (palpitations, tremor) but do not treat the core disorder. Tricyclic antidepressants (e.g. imipramine) are second-line. Start SSRIs at low dose and titrate slowly to minimise initial anxiety.', updated_at = now() WHERE id = 'c0037604-c5c4-4736-be79-1e2da88d5da8';

-- Mental Health: Antipsychotic monitoring
UPDATE akt_questions SET explanation = 'Antipsychotics (especially second-generation e.g. olanzapine, quetiapine, risperidone) require monitoring of weight, lipids, glucose, and HbA1c (metabolic monitoring) due to risk of metabolic syndrome, weight gain, and type 2 diabetes (NICE CG178). Also monitor: ECG (QTc prolongation risk), blood pressure, prolactin (if symptomatic), LFTs, and FBC (clozapine requires regular FBC for agranulocytosis risk). Metabolic monitoring should be done at baseline, 3 months, 6 months, then annually.', updated_at = now() WHERE id = '2cc1052c-eda9-4a0c-9ab4-b341c77014ab';

-- Mental Health: Lithium monitoring
UPDATE akt_questions SET explanation = 'Lithium monitoring in stable patients is every 6 months: lithium level (target 0.4–0.8 mmol/L for maintenance), renal function (U&Es, eGFR — lithium is nephrotoxic), and thyroid function (TFTs — lithium causes hypothyroidism). More frequent monitoring is needed if dose changes, illness, dehydration, or interacting medications. Annual monitoring is too infrequent. At initiation: check levels weekly until stable, then 3-monthly for the first year, then 6-monthly. Lithium has a narrow therapeutic index.', updated_at = now() WHERE id = '2ac42ec9-54c9-46eb-a06b-b2a91329eede';

-- Mental Health: Self-harm management
UPDATE akt_questions SET explanation = 'Self-harm requires a thorough risk assessment (current intent, plan, means, hopelessness, protective factors) and appropriate onward referral: crisis team referral if high risk; routine mental health referral if lower risk but ongoing concerns (NICE CG133). Never ignore, trivialise, or punish self-harm. Provide empathic support. Safety-netting advice and follow-up are essential. Assess for underlying mental health conditions (depression, personality disorder). Medication may be part of treatment but is not the sole management.', updated_at = now() WHERE id = 'c5e3d8d3-68a0-486b-ae6d-4ccbb718dfaf';

-- Mental Health: Alcohol dependence
UPDATE akt_questions SET explanation = 'For alcohol dependence, brief intervention and referral to specialist addiction services are first-line in primary care (NICE CG115). Structured brief advice using FRAMES principles should be offered. Prophylactic thiamine should be given to prevent Wernicke''s encephalopathy. Benzodiazepines (chlordiazepoxide) are used for medically assisted alcohol withdrawal but should be supervised (inpatient or specialist community). Acamprosate or naltrexone may be used to maintain abstinence. Admission is needed for severe withdrawal risk (seizure history, delirium tremens).', updated_at = now() WHERE id = 'aff1a0f2-629f-4921-80a6-f4289dd3f66a';

-- Mental Health: Eating disorder urgent referral
UPDATE akt_questions SET explanation = 'Eating disorders require urgent referral if BMI <15 in adults (or rapidly falling BMI), as this indicates severe malnutrition with risk of medical instability (NICE NG69). Other urgent indications: electrolyte disturbance, bradycardia, hypotension, hypothermia, rapid weight loss, suicidal ideation, or failure of outpatient treatment. BMI 16–17.5 is underweight and warrants timely (not urgent) referral. BMI >18.5 may still need referral if there are concerning behaviours or comorbidities.', updated_at = now() WHERE id = 'df7469d6-9f0b-4b35-9a1a-471a4fd72ac9';

-- Mental Health: Depression PHQ-9 severity
UPDATE akt_questions SET explanation = 'PHQ-9 scoring: 0–4 minimal, 5–9 mild, 10–14 moderate, 15–19 moderately severe, 20–27 severe depression. A score of 16 = moderately severe depression. Management: offer an SSRI (e.g. sertraline) and/or high-intensity psychological therapy (e.g. CBT, IPT). For moderate depression, both options are appropriate. Assess suicide risk. Review in 2–4 weeks. For severe depression (≥20), medication is usually recommended alongside psychological therapy. Mild depression: active monitoring or low-intensity psychological intervention.', updated_at = now() WHERE id = '5e0b2eec-17b3-474b-ae69-b127c5c2a435';

-- Mental Health: Depression severity (PHQ-9 12)
UPDATE akt_questions SET explanation = 'PHQ-9 scoring: 0–4 minimal, 5–9 mild, 10–14 moderate, 15–19 moderately severe, 20–27 severe depression. A score of 12 = moderate depression. For moderate depression, NICE recommends offering either an SSRI (e.g. sertraline, fluoxetine) or high-intensity psychological therapy (CBT, IPT, behavioural activation). Patient preference should guide choice. Assess suicide risk (question 9 of PHQ-9). Arrange follow-up in 2–4 weeks to assess response.', updated_at = now() WHERE id = '5e4eca11-4691-448c-99bf-9dc869a7d471';

-- Mental Health: Suicidal ideation crisis
UPDATE akt_questions SET explanation = 'Suicidal ideation requires same-day urgent assessment — refer to crisis team or arrange emergency mental health assessment. Do not manage with routine referral, reassurance alone, or waiting. Assess risk factors: current plan, means, intent, hopelessness, isolation, substance use, previous attempts. Ensure patient safety. If immediate risk, call emergency services. Medication alone is insufficient without proper risk assessment and safety planning. Follow-up is essential.', updated_at = now() WHERE id = '889da2ee-2916-43aa-9155-0d90a3cdf6fa';

-- Respiratory: Asthma control assessment
UPDATE akt_questions SET explanation = 'Using SABA >3 times per week (or daily) indicates poor asthma control. Peak flow <75% of personal best also indicates poor control. Management: first check inhaler technique and adherence. If adequate, step up — start or increase low-dose ICS (inhaled corticosteroid) as preventer therapy (BTS/SIGN, NICE). Review after 4–8 weeks. Good control = SABA ≤2 times/week, no nocturnal symptoms, no limitation of activities, normal peak flow. Use RCP 3 questions for quick assessment.', updated_at = now() WHERE id = '50d95f30-d648-49a5-86b0-18cacf1807d9';

-- Respiratory: Lung mass investigation
UPDATE akt_questions SET explanation = 'For suspected lung cancer (cough >3 weeks with weight loss, haemoptysis, or CXR mass), arrange urgent CT chest with contrast as the first-line investigation to characterise the mass, assess mediastinal involvement, and guide further management. Refer via the 2-week wait pathway for suspected lung cancer (NICE NG12). CT is superior to plain CXR for staging and characterisation. Bronchoscopy or CT-guided biopsy follows for tissue diagnosis. PET-CT is used for staging.', updated_at = now() WHERE id = '9fe3227b-2bbe-4114-97b3-5cbd97888dcc';

-- Respiratory: COPD exacerbation management
UPDATE akt_questions SET explanation = 'For COPD patients with ≥2 exacerbations per year requiring antibiotics or steroids, add ICS (inhaled corticosteroid) to existing bronchodilator therapy (NICE NG115). If on LAMA only (e.g. tiotropium), add LABA + ICS combination (e.g. budesonide/formoterol). If still exacerbating on dual therapy, consider triple therapy (ICS + LABA + LAMA). ICS reduces exacerbation frequency but increases pneumonia risk. Review regularly and step down if stable. Blood eosinophils may guide ICS use.', updated_at = now() WHERE id = '78f29393-f830-4443-b0c4-09ccd59c916f';

-- Paediatrics: Bedwetting management
UPDATE akt_questions SET explanation = 'Enuresis (bedwetting) in children: first-line management is reassurance and general advice (regular fluid intake, toileting routine, reward systems) for children <7 years, as most will grow out of it. For children ≥7 years where bedwetting persists and is distressing, enuresis alarm is first-line treatment (highest long-term success rate). Desmopressin is second-line if alarm not suitable, not tolerated, or for short-term use (e.g. sleepovers, school trips). Exclude underlying causes: UTI, diabetes, constipation.', updated_at = now() WHERE id = '658b28de-fc33-4003-8e82-7cc1555a509f';

-- Paediatrics: Red flag at 18 months
UPDATE akt_questions SET explanation = 'Not walking by 18 months is a developmental red flag requiring urgent developmental assessment and referral to paediatrics. Typical gross motor milestones: sitting unsupported by 8–9 months, pulling to stand by 12 months, walking by 18 months. Pincer grasp typically develops by 10–12 months. Social smile should be present by 6–8 weeks. Red flags at any age include regression of milestones, lack of response to sound, and persistent abnormal muscle tone (floppy or stiff).', updated_at = now() WHERE id = '860f268a-73e1-44c9-bd4d-2ae214e8b228';

-- NNT calculation
UPDATE akt_questions SET explanation = 'NNT = 1 / ARR. Baseline risk 10%, relative risk reduction (RRR) 25% → ARR = 10% × 0.25 = 2.5%. NNT = 1 / 0.025 = 40. This means 40 people need treatment to prevent one additional adverse event. NNT is a clinically useful measure derived from absolute risk reduction. Lower NNT = more effective treatment. Always consider ARR rather than RRR alone, as RRR can exaggerate benefit in low-risk populations.', updated_at = now() WHERE id = '8169d737-228d-4a73-b71e-781fdbfbeb26';

-- NNT stroke example
UPDATE akt_questions SET explanation = 'NNT = 1 / ARR. ARR = control event rate − treatment event rate = 10% − 7% = 3% (0.03). NNT = 1 / 0.03 = 33.3, rounded to 33. This means 33 people need to be treated to prevent one stroke. NNT provides a clinically meaningful measure of treatment benefit compared to relative risk reduction. Lower NNT indicates a more effective treatment. Always use absolute measures (ARR, NNT) when communicating treatment benefit to patients.', updated_at = now() WHERE id = '80210997-7658-483b-a78e-6025c65ba9aa';

-- ARR calculation
UPDATE akt_questions SET explanation = 'ARR = CER (control event rate) − TER (treatment event rate). Given RRR = (CER − TER) / CER = 25%, and CER = 20%: TER = CER − (RRR × CER) = 20% − (0.25 × 20%) = 20% − 5% = 15%. Therefore ARR = 20% − 15% = 5%. NNT = 1/ARR = 1/0.05 = 20. Relative risk reduction (25%) sounds impressive but the absolute benefit (5%) and NNT (20) provide a more clinically meaningful picture. Always report ARR alongside RRR.', updated_at = now() WHERE id = '27b16817-8e5b-4e28-93f3-9f5a723cbb1d';

-- Dermatology: Changing mole
UPDATE akt_questions SET explanation = 'A changing mole is a red flag for melanoma. NICE NG12 recommends urgent 2-week wait referral to dermatology for any pigmented lesion that is changing, has irregular features (ABCDE criteria), or is new and growing in an adult. Do not biopsy, excise, or "watch and wait" in primary care. Specialist assessment including dermoscopy is needed. Early detection and complete excision is crucial for prognosis — melanoma depth (Breslow thickness) at diagnosis is the strongest prognostic factor.', updated_at = now() WHERE id = '24912c5f-84f5-4bca-ab3a-d0f2938998b7';

-- Endocrinology: Hypothyroidism (duplicate stem fix explanation)
UPDATE akt_questions SET explanation = 'Elevated TSH with low free T4 confirms primary hypothyroidism. Common cause in UK is Hashimoto''s thyroiditis (autoimmune). TSH >10 mU/L with symptoms warrants treatment with levothyroxine. Start at 25–50 mcg (lower in elderly or cardiac patients) and titrate based on TSH. Subclinical hypothyroidism (elevated TSH, normal T4) is treated if TSH >10, or symptomatic, or if planning pregnancy. Secondary hypothyroidism (pituitary failure) shows low TSH AND low T4 — investigate with pituitary function tests and MRI.', updated_at = now() WHERE id = 'aba484b4-cdf6-444d-936e-ca4979a1bb30';

-- Endocrinology: Subclinical hypothyroidism treatment
UPDATE akt_questions SET explanation = 'Subclinical hypothyroidism (elevated TSH with normal free T4) is treated when: TSH >10 mU/L (regardless of symptoms), or TSH 5–10 with symptoms of hypothyroidism, or if planning pregnancy (NICE CKS). A 35-year-old with TSH 12 warrants treatment with levothyroxine. In elderly patients with mild TSH elevation (5–10), treatment is less likely to benefit and may cause harm (atrial fibrillation, bone loss). Monitor every 6–12 months if not treating. Always recheck before starting treatment.', updated_at = now() WHERE id = 'dd412195-c70c-4332-bb14-82a5bf523338';

-- Endocrinology: HbA1c diagnostic threshold
UPDATE akt_questions SET explanation = 'WHO and NICE define type 2 diabetes as HbA1c ≥48 mmol/mol (6.5%). A single reading ≥48 with symptoms (polyuria, polydipsia, weight loss) confirms the diagnosis. In asymptomatic patients, two readings ≥48 on separate occasions are required. Pre-diabetes (non-diabetic hyperglycaemia) is defined as HbA1c 42–47 mmol/mol — offer intensive lifestyle intervention. HbA1c may be unreliable in conditions affecting red cell turnover (haemoglobinopathies, anaemia, pregnancy) — use fasting glucose or OGTT.', updated_at = now() WHERE id = '3819296e-5ef2-44ca-b7ab-fbae843f45d0';

-----------------------------------------------------------
-- PART 3: MORE SHORT STEMS → clinical vignettes
-----------------------------------------------------------

-- Gastroenterology: Cholestatic LFTs →
UPDATE akt_questions SET question = 'A 60-year-old woman presents with pruritus and jaundice. Bloods show bilirubin 85 µmol/L, ALP 450 U/L, ALT 55 U/L. What is the most appropriate first investigation?', explanation = 'Cholestatic LFT pattern (raised bilirubin and ALP disproportionately raised compared to ALT/AST) suggests biliary obstruction or cholestasis. The first investigation is liver ultrasound to assess for bile duct dilatation, gallstones, or masses. Causes: gallstones (most common), pancreatic cancer, cholangiocarcinoma, primary biliary cholangitis (PBC), drug-induced cholestasis. If ultrasound shows dilated ducts, MRCP or ERCP is the next step. If normal ducts, check AMA (anti-mitochondrial antibodies) for PBC.', updated_at = now() WHERE id = 'c169ba50-0612-44d9-8094-175a7a978e63';

-- Gastroenterology: GERD first-line →
UPDATE akt_questions SET question = 'A 42-year-old man presents with a 6-week history of heartburn and acid regurgitation, worse after meals and when lying down. There are no alarm features. What is the most appropriate first-line management?', explanation = 'GERD first-line: lifestyle advice (weight loss if overweight, avoid trigger foods, smaller meals, elevate head of bed, stop smoking, reduce alcohol) and a 4–8 week trial of full-dose PPI (e.g. omeprazole 20 mg OD, lansoprazole 30 mg OD). If symptoms resolve, try stepping down to low-dose PPI or H2-receptor antagonist (ranitidine alternative). If symptoms persist, consider doubling PPI dose or switching PPI. Arrange endoscopy if alarm features: dysphagia, weight loss, GI bleeding, or age ≥55 with new symptoms.', updated_at = now() WHERE id = '28960844-6763-4829-adbc-4d20c59a458e';

-- Gastroenterology: UK pancreatitis cause:
UPDATE akt_questions SET question = 'A 50-year-old woman presents with severe epigastric pain radiating to the back, nausea, and vomiting. Amylase is 1200 U/L. What is the most common cause of acute pancreatitis in the UK?', explanation = 'In the UK, gallstones are the most common cause of acute pancreatitis (40–50%), followed by alcohol (25–30%). Other causes: hypertriglyceridaemia, drugs (azathioprine, valproate, steroids), ERCP, trauma, autoimmune, and genetic causes. Always check LFTs (raised ALT supports gallstone aetiology), lipase/amylase, and arrange abdominal ultrasound within 24 hours to identify gallstones. Gallstone pancreatitis may require ERCP and subsequent cholecystectomy during the same admission.', updated_at = now() WHERE id = '6ba2f759-5692-475b-8659-4fc1bcff9bf9';

-- Gastroenterology: Low-risk alcohol →
UPDATE akt_questions SET question = 'A 45-year-old man asks about safe alcohol consumption. According to UK guidelines, what is the recommended low-risk weekly limit?', explanation = 'UK Chief Medical Officers'' guidelines recommend no more than 14 units per week for both men and women, spread over 3 or more days with alcohol-free days. One unit = 10 mL pure alcohol (approximately half a pint of average-strength beer, a small glass of wine, or a single measure of spirits). Binge drinking (>6 units in one session for women, >8 for men) is harmful even if weekly total is within limits. High-risk drinking is >14 units/week. Pregnant women should avoid alcohol completely.', updated_at = now() WHERE id = '2b172d0d-a08f-4bc5-b728-33c7b5ef7a72';

-- Gastroenterology: Dyspepsia + weight loss + anaemia →
UPDATE akt_questions SET question = 'A 62-year-old man presents with 8 weeks of dyspepsia, 6 kg unintentional weight loss, and iron deficiency anaemia (Hb 98 g/L, ferritin 5 µg/L). What is the most appropriate next step?', explanation = 'Dyspepsia combined with weight loss and anaemia constitutes alarm symptoms requiring urgent 2-week wait referral for suspected upper GI cancer (NICE NG12). This combination suggests possible gastric or oesophageal cancer. Do not offer a PPI trial or routine referral — arrange urgent upper GI endoscopy. Other alarm features include dysphagia, persistent vomiting, haematemesis, melaena, and epigastric mass. Early diagnosis significantly improves prognosis.', updated_at = now() WHERE id = '70da1672-e8fe-4409-b3c4-252a1aefd247';

-- Haematology: DVT treatment →
UPDATE akt_questions SET question = 'A 55-year-old man is diagnosed with an unprovoked proximal DVT in his left leg. He has no contraindications to anticoagulation. What is the most appropriate first-line treatment?', explanation = 'DOACs (direct oral anticoagulants) — rivaroxaban or apixaban — are now first-line for DVT treatment (NICE NG158). Rivaroxaban: 15 mg BD for 21 days then 20 mg OD. Apixaban: 10 mg BD for 7 days then 5 mg BD. DOACs are preferred over warfarin due to efficacy, convenience, lower bleeding risk, and no monitoring requirement. Warfarin (target INR 2.0–3.0) is an alternative. Duration: provoked DVT = 3 months; unprovoked = 3–6 months with assessment for extended treatment. Compression stockings help symptom control.', updated_at = now() WHERE id = 'a415881a-5ad7-4e7d-8eeb-eebdc53725b1';

-- Infectious Diseases: TB is:
UPDATE akt_questions SET question = 'A 30-year-old man from an endemic area presents with a persistent productive cough for 4 weeks, night sweats, weight loss, and haemoptysis. CXR shows upper lobe cavitation. What is the most likely diagnosis?', explanation = 'Tuberculosis (TB) is caused by Mycobacterium tuberculosis, spread via airborne droplets. Pulmonary TB is the most common form. Diagnosis: sputum samples (×3 for acid-fast bacilli and culture — culture is gold standard), CXR (upper lobe cavitation typical), and consider interferon-gamma release assay (IGRA) or Mantoux test. Treatment: 6-month regimen of RIPE (rifampicin + isoniazid for 6 months, pyrazinamide + ethambutol for first 2 months). TB is a notifiable disease — inform public health.', updated_at = now() WHERE id = '2634e54a-6c31-4807-876d-194177589816';

-- Ophthalmology: Flashes + floaters + visual field defect =
UPDATE akt_questions SET question = 'A 60-year-old myopic man presents with a sudden shower of floaters, flashing lights, and a "curtain" coming across his vision in the left eye. What is the most likely diagnosis?', explanation = 'The triad of flashes, floaters, and visual field defect (described as a "curtain" or "shadow") strongly suggests retinal detachment. This is an ophthalmic emergency requiring same-day referral to ophthalmology. Risk factors include myopia, increasing age, previous cataract surgery, and trauma. Delay in treatment risks permanent visual loss. New onset of floaters alone may represent posterior vitreous detachment, which is usually benign but should prompt urgent assessment to exclude retinal tear or detachment.', updated_at = now() WHERE id = 'b16513e3-0d05-4d65-b5f0-47496335c455';

-- Ophthalmology: Red eye requiring same-day referral:
UPDATE akt_questions SET question = 'A 70-year-old woman presents with sudden severe pain in her right eye, reduced vision, haloes around lights, and a red eye. Her pupil is mid-dilated and fixed. What is the most likely diagnosis?', explanation = 'Acute angle-closure glaucoma requires same-day emergency ophthalmology referral as it can cause permanent vision loss within hours. Features: severe eye pain, red eye, reduced vision, haloes around lights, nausea/vomiting, hazy cornea, mid-dilated fixed pupil. Emergency treatment: pilocarpine eye drops (to constrict pupil), IV acetazolamide, and definitive treatment is peripheral iridotomy. Conjunctivitis (bilateral, discharge, normal vision), dry eye, and blepharitis (lid margin) are managed in primary care.', updated_at = now() WHERE id = 'a3b1c6c7-8eed-4a8d-b85d-99a65d0bb2df';

-- Oncology: Weight loss first test:
UPDATE akt_questions SET question = 'A 58-year-old man presents with unintentional weight loss of 8 kg over 3 months. He has no other symptoms. What is the most appropriate initial set of investigations?', explanation = 'Unexplained weight loss (>5% in 6–12 months) requires investigation. First-line bloods: FBC (anaemia/malignancy), U&Es (renal function), LFTs (liver disease/metastases), TFTs (hyperthyroidism), glucose/HbA1c (diabetes), calcium (hypercalcaemia of malignancy), CRP/ESR (inflammation). Also arrange CXR (lung cancer, TB). If initial tests are abnormal or weight loss persists, consider CT chest/abdomen/pelvis, endoscopy, and tumour markers. Red flags: age >50, smoking history, dysphagia, change in bowel habit.', updated_at = now() WHERE id = '0336c759-40db-4c2a-92d3-54ac7397d1b3';

-- Neurology: TIA management:
UPDATE akt_questions SET question = 'A 72-year-old man experienced sudden-onset left arm weakness and dysphasia lasting 30 minutes, which has now fully resolved. What is the most appropriate immediate management?', explanation = 'TIA management: give aspirin 300 mg immediately (unless contraindicated), and refer urgently to TIA clinic for assessment within 24 hours (NICE NG128). Specialist assessment includes brain imaging (MRI/CT), carotid imaging (if anterior circulation), and cardiac assessment. If AF is identified, anticoagulate (DOAC preferred). Start secondary prevention: clopidogrel 75 mg long-term, statin, antihypertensive. Address modifiable risk factors (BP, cholesterol, smoking, diabetes). ABCD2 score is no longer used for decision-making in current NICE guidance.', updated_at = now() WHERE id = '6f24df5b-cba3-44fd-80b8-c4db34b39f14';

-- Neurology: Most common dementia type:
UPDATE akt_questions SET question = 'A 78-year-old man is referred to the memory clinic with progressive memory loss over 12 months. Cognitive testing confirms dementia. What is the most common type of dementia?', explanation = 'Alzheimer''s disease is the most common type of dementia, accounting for 60–70% of cases. Followed by vascular dementia (~20%), mixed dementia (Alzheimer''s + vascular), Lewy body dementia (visual hallucinations, fluctuating cognition, parkinsonism), and frontotemporal dementia (personality/behavioural changes, younger onset). Alzheimer''s presents with progressive memory loss (especially episodic memory), language difficulties, and visuospatial problems. Treatment: acetylcholinesterase inhibitors (donepezil, rivastigmine, galantamine) for mild-to-moderate disease.', updated_at = now() WHERE id = '6e8b90b8-9ef4-42b6-83d5-18337c1d5c30';

-- Respiratory: COPD oxygen target:
UPDATE akt_questions SET question = 'A 68-year-old man with severe COPD is acutely breathless. SpO2 is 82% on air. He has a history of type 2 respiratory failure. What is the target oxygen saturation?', explanation = 'For COPD patients at risk of hypercapnic respiratory failure (type 2 respiratory failure), target SpO2 is 88–92% (BTS guidelines). Higher saturations (>92%) can suppress hypoxic drive, leading to CO2 retention and respiratory acidosis. Use a 24% or 28% Venturi mask for controlled oxygen delivery. Monitor with ABGs. Long-term oxygen therapy (LTOT) is indicated if PaO2 <7.3 kPa on two occasions or 7.3–8.0 kPa with complications. LTOT must be used ≥15 hours/day for mortality benefit.', updated_at = now() WHERE id = '0671d9e2-d9fe-46c0-9447-64adbdfffba8';

-- Prescribing: ACE-i angioedema →
UPDATE akt_questions SET question = 'A 60-year-old man on ramipril for 3 weeks presents with sudden lip and tongue swelling. He has no urticaria or wheeze. What is the most likely cause?', explanation = 'ACE inhibitor angioedema is a rare but serious side effect (0.1–0.7% of patients). It presents with swelling of face, lips, tongue, and throat — can cause airway obstruction. More common in the first few weeks of treatment but can occur at any time. Risk factors: African/Caribbean ethnicity, prior angioedema. If angioedema occurs: stop ACE inhibitor immediately and never restart. Switch to an alternative (calcium channel blocker, or ARB with caution as cross-reactivity is rare but possible). If airway compromise, treat as anaphylaxis (IM adrenaline, 999).', updated_at = now() WHERE id = 'ee290ed5-0eb3-4976-97f8-e1df6a55c31f';

-- Renal: PSA screening in UK:
UPDATE akt_questions SET question = 'A 60-year-old man with no urinary symptoms asks about PSA testing. What should he be told about PSA screening in the UK?', explanation = 'There is no national PSA screening programme in the UK due to concerns about overdiagnosis and overtreatment. However, men aged ≥50 who request testing after informed discussion should be offered a PSA test (NHS Prostate Cancer Risk Management Programme). The discussion should cover: PSA can be raised in benign conditions (BPH, prostatitis, UTI), a normal PSA does not exclude cancer, and abnormal results may lead to further investigations (MRI, biopsy) that carry risks. If PSA is raised, consider re-testing and referral.', updated_at = now() WHERE id = '6ac47014-238b-4032-928a-d52e9af6a46a';

-- Renal: Refer CKD when:
UPDATE akt_questions SET question = 'A 55-year-old woman with type 2 diabetes has CKD stage 3b (eGFR 38). Her ACR is 5 mg/mmol. Under which circumstances should she be referred to nephrology?', explanation = 'Refer CKD to nephrology when: eGFR <30 (stage 4–5), sustained decrease in eGFR >25% or >15 mL/min in 12 months, ACR ≥70 mg/mmol (or ≥30 with haematuria), uncontrolled hypertension despite ≥4 agents, suspected renal artery stenosis, or suspected rare/genetic renal disease (NICE NG203). Stable CKD stage 3a–3b with controlled BP and low proteinuria can usually be managed in primary care. Optimise BP, prescribe ACEi/ARB if proteinuria, and avoid nephrotoxic drugs.', updated_at = now() WHERE id = '0087cfb4-a2ec-4f50-9b74-e1e2d7554430';

-- Renal: CKD eGFR stage
UPDATE akt_questions SET explanation = 'CKD staging by eGFR (NICE NG203): Stage 1 (≥90) with evidence of kidney damage, Stage 2 (60–89) with kidney damage, Stage 3a (45–59), Stage 3b (30–44), Stage 4 (15–29), Stage 5 (<15 or on dialysis). eGFR 25 = Stage 4 (severe CKD). At stage 4, refer to nephrology and prepare for renal replacement therapy discussions. Monitor for complications: anaemia, bone disease, acidosis, hyperkalaemia. Avoid nephrotoxic medications and adjust drug doses for renal function.', updated_at = now() WHERE id = '176a150f-d2f3-4de6-af52-00eac2682511';

-- Renal: CKD 3a eGFR
UPDATE akt_questions SET explanation = 'CKD staging by eGFR (NICE NG203): Stage 1 ≥90 (with evidence of kidney damage), Stage 2 60–89 (with kidney damage), Stage 3a 45–59, Stage 3b 30–44, Stage 4 15–29, Stage 5 <15 (or on dialysis). Stage 3a requires monitoring of eGFR, ACR, BP, and cardiovascular risk management. Refer to nephrology if eGFR <30, rapid decline, or significant proteinuria. Prescribe ACEi/ARB if ACR ≥30 mg/mmol. Avoid NSAIDs and monitor for complications.', updated_at = now() WHERE id = '7df30a7a-b90b-4a4a-8601-8b721144ae70';

-- Mental Health: Postnatal depression screening tool:
UPDATE akt_questions SET question = 'A 28-year-old woman attends her 6-week postnatal check. She reports feeling low, tearful, and disconnected from her baby. What validated tool should be used to screen for postnatal depression?', explanation = 'The Edinburgh Postnatal Depression Scale (EPDS) is the validated screening tool for postnatal depression. Score 0–30: ≥13 indicates likely depression, ≥10 indicates possible depression. Question 10 specifically asks about self-harm and must always be reviewed. If EPDS is positive, assess risk (including to mother and baby) and offer treatment: mild-to-moderate = psychological therapy (guided self-help or CBT); moderate-to-severe = SSRI (sertraline is commonly used in breastfeeding). Refer to perinatal mental health services if severe, psychotic features, or risk.', updated_at = now() WHERE id = '7a34785e-3e79-455a-924e-42f0507e77bb';

-- Mental Health: Eating disorder red flag:
UPDATE akt_questions SET question = 'A 16-year-old girl is brought in by her mother who is concerned about weight loss. BMI is 16.5. On examination, her hands are cold and she has a resting heart rate of 50. Which finding is the most significant red flag?', explanation = 'Bradycardia (resting HR <60) in an eating disorder indicates cardiovascular compromise from malnutrition and is a significant red flag requiring urgent assessment. Other red flags: rapid weight loss, BMI <15, hypotension, hypothermia, electrolyte abnormalities (particularly hypokalaemia), amenorrhoea, lanugo hair, Russell''s sign (knuckle calluses from self-induced vomiting), dental erosion. Urgent referral needed if medical instability, severe malnutrition (BMI <15), suicidal ideation, or outpatient treatment failing (NICE NG69). Eating disorders carry high mortality.', updated_at = now() WHERE id = 'de827346-da44-4050-af01-1a33afb1449c';

-- Mental Health: Antidepressant review timing:
UPDATE akt_questions SET question = 'A 35-year-old woman has been started on sertraline 50 mg for moderate depression. When should she first be reviewed?', explanation = 'Review at 2–4 weeks after starting an antidepressant to assess response, side effects, adherence, and risk (NICE CG90/NG222). Warn the patient that benefits may take 4–6 weeks to appear. If no response by 6 weeks at adequate dose, consider increasing dose or switching antidepressant. If effective, continue for at least 6–12 months after remission (longer if recurrent depression: ≥2 years). When stopping, taper gradually over at least 4 weeks to minimise withdrawal symptoms. Monitor for relapse during and after tapering.', updated_at = now() WHERE id = '5d106a66-b6fb-4325-a50f-07a40fe4e631';

-----------------------------------------------------------
-- PART 4: REMAINING SHORT EXPLANATIONS (stem acceptable)
-----------------------------------------------------------

-- Musculoskeletal: Initial sciatica management
UPDATE akt_questions SET explanation = 'Sciatica first-line management is staying active (avoid bed rest), simple analgesia (paracetamol, NSAIDs), and physiotherapy. Most cases resolve within 6–12 weeks. MRI is not first-line and should be reserved for suspected cauda equina syndrome, progressive neurological deficit, or symptoms persisting >6 weeks where surgery is being considered. Bed rest worsens outcomes. Epidural steroid injections may be considered in secondary care. Surgical referral (microdiscectomy) if severe, progressive, or unresponsive to conservative management.', updated_at = now() WHERE id = '73e81364-61af-412d-b91b-6969418a8c0f';

-- Musculoskeletal: Acute gout first-line
UPDATE akt_questions SET explanation = 'Acute gout first-line treatment is colchicine (500 mcg BD–TDS, started within 12 hours of onset) or NSAID (e.g. naproxen 750 mg then 250 mg TDS) if no contraindications (NICE CKS). Allopurinol and febuxostat are urate-lowering therapies for prevention — they must NOT be started during an acute attack (can worsen symptoms) but should not be stopped if already taking. If NSAIDs and colchicine are both contraindicated, short course of prednisolone (30–40 mg for 5 days) or intra-articular steroid injection.', updated_at = now() WHERE id = 'a2310f90-90e0-409c-bf34-a16f453cf046';

-- Musculoskeletal: Allopurinol timing
UPDATE akt_questions SET explanation = 'Allopurinol (urate-lowering therapy) should be started after the acute gout attack has fully settled — typically ≥2 weeks after resolution. Starting during an acute attack can prolong or worsen the flare (NICE CKS). Once initiated, start low (100 mg OD) and titrate by 100 mg increments every few weeks to target urate <360 µmol/L. Prophylactic colchicine (500 mcg OD) or NSAID should be co-prescribed for the first 6 months of ULT to prevent flares. Do not stop allopurinol during future attacks once established.', updated_at = now() WHERE id = '7da8b38d-414c-4974-81cd-7eda836ac7ed';

-- Musculoskeletal: Back pain imaging
UPDATE akt_questions SET explanation = 'Imaging for low back pain is only indicated when red flags are present (NICE NG59): cauda equina symptoms (saddle anaesthesia, bladder/bowel dysfunction), suspected malignancy (unexplained weight loss, history of cancer, age >50), suspected infection (fever, IV drug use), suspected fracture (trauma, osteoporosis, steroid use), or progressive neurological deficit. Duration of pain alone, anxiety about diagnosis, or occupation are not indications for imaging. Inappropriate imaging can lead to overdiagnosis and unnecessary interventions.', updated_at = now() WHERE id = '0255fd6c-7015-437f-af51-763913f81ff0';

-- Musculoskeletal: GCA visual disturbance
UPDATE akt_questions SET explanation = 'Visual disturbance (blurred vision, diplopia, amaurosis fugax, or sudden vision loss) in suspected giant cell arteritis (GCA) requires same-day urgent action: start high-dose prednisolone (40–60 mg OD; if visual symptoms, IV methylprednisolone may be given) and arrange urgent ophthalmology and rheumatology assessment (NICE NG228). GCA can cause permanent bilateral blindness if untreated. Do not wait for biopsy results before starting steroids. Other symptoms (headache, scalp tenderness, jaw claudication) are important but visual involvement is the most urgent.', updated_at = now() WHERE id = '92b745a8-efbf-469f-86ca-058e1748ba7c';

-- Musculoskeletal: Urgent RA referral
UPDATE akt_questions SET explanation = 'Symmetrical small joint swelling (MCP, PIP, MTP joints) with morning stiffness >30 minutes suggests inflammatory arthritis, most likely rheumatoid arthritis. This requires urgent rheumatology referral — ideally within 3 weeks (NICE NG100). Early treatment with DMARDs (methotrexate first-line) prevents irreversible joint damage. Check rheumatoid factor, anti-CCP antibodies, CRP, ESR, and X-rays. Do not delay referral for investigation results. The "window of opportunity" for treatment is within the first 3–6 months of symptom onset.', updated_at = now() WHERE id = 'ab192b7a-9f35-4cdd-9cfb-32e2e28e8d79';

-- Musculoskeletal: Vitamin D replacement
UPDATE akt_questions SET explanation = 'Standard vitamin D replacement for deficiency (<25 nmol/L): loading dose of approximately 300,000 IU total, given as weekly doses (e.g. 20,000 IU weekly for 15 weeks, or 50,000 IU weekly for 6 weeks) or daily doses (e.g. 4,000 IU daily for 10 weeks). Maintenance dose: 800–2,000 IU daily thereafter. For insufficiency (25–50 nmol/L), maintenance dose alone may suffice. Monitor calcium levels, especially in granulomatous disease or primary hyperparathyroidism where vitamin D supplementation can cause hypercalcaemia.', updated_at = now() WHERE id = '20393e9c-996f-4393-8f05-70cd38d315ef';

-- Musculoskeletal: DEXA scanning indications
UPDATE akt_questions SET explanation = 'DEXA scan is indicated for: patients with a fragility fracture (to confirm osteoporosis and guide treatment), those identified as high risk on FRAX or QFracture (before starting treatment), and specific high-risk groups (e.g. patients on long-term steroids, early menopause, conditions causing bone loss). Age >65 alone is not an indication without risk factors. A 65-year-old woman with a fragility fracture definitely qualifies. Use FRAX/QFracture to assess fracture risk and guide DEXA referral (NICE CG146).', updated_at = now() WHERE id = 'e15f4f30-6199-48e6-bda8-037d105ca23c';

-- Musculoskeletal: Tennis elbow
UPDATE akt_questions SET explanation = 'Tennis elbow (lateral epicondylitis) first-line management is conservative: activity modification (avoid aggravating movements), analgesia (paracetamol, topical NSAIDs), and physiotherapy (eccentric exercises). Most cases (80–90%) resolve within 12 months. Steroid injection is second-line and may provide short-term relief but is associated with higher recurrence rates. Ice application and forearm bracing may help. Surgery (open or arthroscopic debridement) is for refractory cases that have failed conservative management over 6–12 months.', updated_at = now() WHERE id = '55aa4bd8-8612-49f0-bb78-c2c475e81c92';

-- Musculoskeletal: Hypercalcaemia in primary care
UPDATE akt_questions SET explanation = 'Primary hyperparathyroidism is the most common cause of mild hypercalcaemia detected incidentally in primary care (raised calcium with elevated or inappropriately normal PTH). Malignancy is the second most common cause overall and typically causes more severe hypercalcaemia (often with bone pain, weight loss). Always check PTH alongside calcium. If PTH is high/normal with raised calcium, refer to endocrinology. If PTH is suppressed, investigate for malignancy (myeloma screen, CXR, CT). Other causes: sarcoidosis, thiazides, vitamin D excess.', updated_at = now() WHERE id = 'c6d4d65b-590f-4933-aacf-fc6b431f7739';

-- Musculoskeletal: Bisphosphonate counselling
UPDATE akt_questions SET explanation = 'Key counselling for bisphosphonates (alendronate, risedronate): take on an empty stomach first thing in the morning with a full glass of plain water. Remain upright (sitting or standing) for at least 30 minutes after taking to prevent oesophageal irritation and ulceration. Wait ≥30 minutes before eating, drinking, or taking other medications. Calcium and vitamin D supplements should be taken at a different time of day (calcium impairs bisphosphonate absorption). Report any difficulty swallowing, chest pain, or new heartburn.', updated_at = now() WHERE id = '375a4f25-0a56-4ace-9e8e-76cd25fcd6a0';

-- Musculoskeletal: Adjusted calcium
UPDATE akt_questions SET explanation = 'Adjusted (corrected) calcium accounts for albumin levels, as approximately 40% of serum calcium is protein-bound. In hypoalbuminaemia (common in elderly, liver disease, nephrotic syndrome), total calcium appears falsely low while ionised (active) calcium is normal. Formula: adjusted calcium = total calcium + 0.02 × (40 − albumin in g/L). Always use adjusted calcium when interpreting results. If adjusted calcium is raised, check PTH to distinguish primary hyperparathyroidism from other causes.', updated_at = now() WHERE id = '729a092f-058e-49f0-a2e3-7f07335b268d';

-- Neurology: Headache with papilloedema
UPDATE akt_questions SET explanation = 'Headache with papilloedema (swelling of the optic disc) suggests raised intracranial pressure and requires urgent referral for neuroimaging (CT/MRI head). Causes include brain tumour, idiopathic intracranial hypertension (typically overweight young women), cerebral venous sinus thrombosis, and intracranial abscess. NICE NG12 recommends urgent referral if suspected brain tumour (progressive headache, new neurological deficit, personality change). Tension-type headache and migraine do not cause papilloedema. Cluster headache causes autonomic features but not papilloedema.', updated_at = now() WHERE id = 'df172d8f-c0cf-4e01-8549-275993ed7526';

-- Neurology: TIA symptoms
UPDATE akt_questions SET explanation = 'A TIA presents with sudden-onset focal neurological symptoms (unilateral weakness, speech disturbance, visual loss, facial droop) that resolve completely, usually within minutes to hours (maximum 24 hours). The pattern of deficits should correspond to a vascular territory. Gradual onset (e.g. over hours/days) is not typical and suggests other diagnoses (e.g. migraine aura, space-occupying lesion). Non-focal symptoms (generalised dizziness, bilateral weakness, confusion alone) are not typical of TIA. Crescendo TIAs (≥2 in 7 days) require immediate assessment.', updated_at = now() WHERE id = 'ec5da949-0972-4de8-829c-3be9aa7ec124';

-- Paediatrics: Autism features
UPDATE akt_questions SET explanation = 'Poor eye contact is a key early feature of autism spectrum disorder (ASD), along with social communication difficulties (difficulty understanding social cues, maintaining conversation, understanding emotions), restricted/repetitive interests and behaviours, and sensory sensitivities. In children, watch for delayed language, lack of pointing or showing, preference for solitary play, and difficulty with pretend play. Refer to paediatrician or child development service if features are present (NICE CG128/CG170). Diagnosis is made by specialist multidisciplinary team.', updated_at = now() WHERE id = '2fcaa0da-9ccd-4e44-a175-2b583e4a0970';

-- Paediatrics: ADHD core symptoms
UPDATE akt_questions SET explanation = 'ADHD core symptoms are inattention, hyperactivity, and impulsivity — present in multiple settings (home and school) from before age 12 (NICE NG87). Inattention: difficulty sustaining attention, easily distracted, forgetful. Hyperactivity: fidgeting, leaving seat, running/climbing. Impulsivity: interrupting, difficulty waiting turn. Diagnosis requires specialist assessment. Aggression, depression, and anxiety may be comorbidities but are not core diagnostic features. First-line treatment: parent training (under 5), then methylphenidate (6+). Non-pharmacological interventions alongside medication.', updated_at = now() WHERE id = '288b71c6-eb67-4ea5-a114-afff5c32b256';

-- Paediatrics: Failure to thrive
UPDATE akt_questions SET explanation = 'Failure to thrive (faltering growth) is indicated by weight crossing downward through centile lines on the growth chart (e.g. falling from 50th to 9th centile over time). A single measurement below a centile is not sufficient — the trend matters. Causes: inadequate intake (feeding difficulties, neglect), malabsorption (coeliac disease, cow''s milk allergy), increased requirements (chronic illness, congenital heart disease). Assessment: detailed feeding history, growth chart review, examination for organic causes. Refer to paediatrics if organic cause suspected or not improving.', updated_at = now() WHERE id = '88f0533b-225e-4a43-93b5-cff8872570d9';

-- Paediatrics: Safeguarding documentation
UPDATE akt_questions SET explanation = 'Safeguarding documentation must be factual, contemporaneous (written at the time), detailed, and objective. Record exact words used by the child or parent (verbatim quotes in quotation marks), physical findings with body maps, and the professional''s assessment and actions taken. Vague terms (e.g. "seems fine"), delays in recording, and verbal-only communication are poor practice and medicolegally risky. Document who was present, who was informed, and what follow-up was arranged. Documentation may be used in court proceedings.', updated_at = now() WHERE id = '765df09b-f10e-4bd1-9527-6edcf981f9ae';

-- Paediatrics: Non-blanching rash management
UPDATE akt_questions SET explanation = 'Fever with non-blanching rash and irritability in a child are red flags for meningococcal disease (meningitis/septicaemia). This requires immediate action: give IM benzylpenicillin (300 mg if <1 year, 600 mg if 1–9 years, 1.2 g if ≥10 years) unless history of anaphylaxis to penicillin, and call 999 for emergency transfer. Do not delay for investigations. Meningococcal disease can deteriorate rapidly. Early antibiotic administration is life-saving. Other causes (ITP, HSP) can be considered once meningococcal disease is excluded.', updated_at = now() WHERE id = 'f4ab6a90-6e19-4779-9aec-35f84da1683a';

-- Palliative Care: End-of-life planning
UPDATE akt_questions SET explanation = 'Advance care planning should involve the patient''s preferences, values, and wishes while they still have capacity (Mental Capacity Act 2005). Discussions should cover: preferred place of care and death, treatment escalation plans, DNACPR if appropriate, lasting power of attorney, and advance decisions to refuse treatment. It should not be avoided, delayed until crisis, or decided solely by clinicians. Involve family if the patient wishes. Document clearly in the patient''s record and share with relevant services (ambulance, out-of-hours).', updated_at = now() WHERE id = '56cbfce6-a16e-43ee-a16a-10c479a1afd1';

-- Palliative Care: DNACPR discussion
UPDATE akt_questions SET explanation = 'DNACPR discussions should be initiated sensitively and early when appropriate — ideally as part of advance care planning while the patient has capacity. Involve the patient in the discussion if they have capacity (though consent is not legally required). If the patient lacks capacity, discuss with family/those close to them and act in best interests. Document the discussion, decision, and rationale clearly. DNACPR is not a decision to withhold other treatments — it only relates to CPR. Review regularly as clinical circumstances change.', updated_at = now() WHERE id = '5875c111-5b7b-48a4-a7e6-bf18055e3f17';

-- Palliative Care: DNACPR correct statement
UPDATE akt_questions SET explanation = 'DNACPR applies only to cardiopulmonary resuscitation — it does not mean withholding other treatments (antibiotics, fluids, nutrition, pain relief). Key points: it does not legally require patient consent (but discussion is good practice and recommended by GMC), it is not permanent and should be reviewed regularly, family signature is not required, and the decision is ultimately a clinical one (not the patient''s or family''s "choice" but made in best interests). All other active and comfort treatments continue unless separately decided otherwise.', updated_at = now() WHERE id = '3fc22233-e6c8-414f-b9d5-6c35d77a3db3';

-- Palliative Care: Last days of life indicator
UPDATE akt_questions SET explanation = 'Terminal secretions (often called "death rattle") indicate the last hours to days of life. They result from pooled oropharyngeal secretions the patient can no longer clear. This is a late sign. Other indicators of the dying phase: reduced consciousness, reduced oral intake, Cheyne-Stokes breathing, mottled skin, and peripheral cyanosis. Reduced appetite and mild pain can occur much earlier in the illness trajectory. Management: reposition, glycopyrronium or hyoscine to reduce secretions. Reassure family that it is usually not distressing to the patient.', updated_at = now() WHERE id = 'a8576806-8c78-4419-aa11-9a01651b77b3';

-- Palliative Care: Falls risk medication
UPDATE akt_questions SET explanation = 'Benzodiazepines significantly increase falls risk in elderly patients due to sedation, impaired balance, reduced reaction time, and cognitive impairment (NICE CG161). They are among the highest-risk medications for falls. Other high-risk medications include: opioids, antihypertensives (postural hypotension), antipsychotics, antidepressants (especially TCAs and SSRIs), and anticholinergics. ACE inhibitors may cause mild postural hypotension. Paracetamol, statins, and metformin do not typically increase falls risk. Always review medications in patients with recurrent falls.', updated_at = now() WHERE id = 'baa07541-a240-4390-ac7b-3afdea8b3118';

-- Palliative Care: Frailty features
UPDATE akt_questions SET explanation = 'Frailty is characterised by the "Fried phenotype" criteria: unintentional weight loss (>4.5 kg in a year), self-reported exhaustion, low physical activity, slow walking speed, and weak grip strength (≥3 of 5 = frail; 1–2 = pre-frail). Alternatively, the Clinical Frailty Scale (1–9) can be used. Hypertension, diabetes, and osteoarthritis alone do not define frailty — though they may contribute. Polypharmacy is associated with frailty but is not diagnostic. Frailty assessment should trigger comprehensive geriatric assessment and advance care planning.', updated_at = now() WHERE id = '985b5ed8-ae3d-455a-9547-186f6ea9fc6b';

-- Prescribing: NSAIDs risk
UPDATE akt_questions SET explanation = 'Patients with CKD stage 3+ are at highest risk from NSAIDs. NSAIDs reduce renal blood flow by inhibiting prostaglandin synthesis, causing AKI, fluid retention, hyperkalaemia, and worsening CKD. The "triple whammy" (NSAID + ACEi/ARB + diuretic) is particularly dangerous. Other high-risk groups: heart failure (fluid retention, worsening), peptic ulcer disease (GI bleeding), elderly (all risks compounded), and patients on anticoagulants (bleeding risk). Use paracetamol or topical NSAIDs as alternatives. If NSAID essential, use lowest dose for shortest duration with gastroprotection.', updated_at = now() WHERE id = '411c9d7b-3506-4a64-a495-0a17f054732d';

-- Prescribing: Benzodiazepine risk
UPDATE akt_questions SET explanation = 'Benzodiazepines carry major risk of physical and psychological dependence, tolerance, and withdrawal (seizures, rebound anxiety, insomnia). Prescribe for short-term use only (2–4 weeks maximum, NICE CG113). Elderly patients are particularly vulnerable to adverse effects: falls, cognitive impairment, paradoxical agitation, and respiratory depression. Withdrawal should be gradual (reduce dose by approximately 10% every 1–2 weeks). Hypertension, significant weight gain, and hyperglycaemia are not typical benzodiazepine side effects.', updated_at = now() WHERE id = 'd807e2ad-2bb0-4256-97ae-13b91869fcf9';

-- Sexual Health: Routine STI screening
UPDATE akt_questions SET explanation = 'Routine STI screening targets: chlamydia screening is offered to all sexually active under-25s annually and on change of partner (NCSP). All patients at risk should also be tested for gonorrhoea, syphilis, and HIV. HIV testing should be normalised and offered to all, especially: MSM, multiple partners, IV drug users, patients from high-prevalence areas, and those with indicator conditions (NICE/BHIVA). Use NAATs (nucleic acid amplification tests) for chlamydia and gonorrhoea (self-taken vulvovaginal or urine samples). Syphilis and HIV are screened with serology.', updated_at = now() WHERE id = 'd6d505df-7f8e-4e09-a5bb-fc007651e3ea';

-- Sexual Health: HIV testing indicator conditions
UPDATE akt_questions SET explanation = 'HIV testing should be offered to patients with indicator conditions as per BHIVA/NICE guidelines: TB, lymphoma, cervical cancer, herpes zoster (shingles in <50), hepatitis B/C, unexplained lymphadenopathy, unexplained weight loss, oral candida, pneumocystis pneumonia, and seborrhoeic dermatitis (severe/recurrent). HIV testing should be normalised and offered routinely in high-prevalence areas (>2 per 1,000). It should not be restricted to "high-risk" groups only. Opt-out testing (offering to everyone) reduces stigma and increases uptake.', updated_at = now() WHERE id = 'fc82c4f8-e8ac-4c99-9edf-253f2d12267c';

-- Women's Health: Cervical screening
UPDATE akt_questions SET explanation = 'Cervical screening in England (NHS CSP): ages 25–49 every 3 years, ages 50–64 every 5 years. Primary HPV testing is used first — if high-risk HPV negative, return to routine recall. If HPV positive, cytology is performed: if normal, repeat HPV test in 12 months; if abnormal, refer for colposcopy. Screening starts at 25 (not earlier) due to high prevalence of transient HPV infection in younger women and low cancer risk. HPV vaccination reduces but does not eliminate need for screening.', updated_at = now() WHERE id = 'df27ae02-eeef-401c-93a5-9a2ba100aaa8';

-- Women's Health: Postmenopausal bleeding
UPDATE akt_questions SET question = 'A 60-year-old woman presents with vaginal bleeding. Her last menstrual period was 8 years ago. She is not on HRT. What is the most appropriate next step?', explanation = 'Postmenopausal bleeding (any vaginal bleeding ≥12 months after last period) is a red flag requiring urgent 2-week wait referral to gynaecology for suspected endometrial cancer (NICE NG12). Investigations include transvaginal ultrasound (endometrial thickness ≥4 mm is abnormal and requires biopsy), hysteroscopy, and endometrial sampling. Most cases are benign (atrophic vaginitis, endometrial polyps, cervical pathology) but endometrial cancer must be excluded. Do not delay referral — even a single episode of PMB requires investigation.', updated_at = now() WHERE id = '2fbf150b-7e7e-40e7-b62a-c2988434e250';

-- Prescribing: Hyperkalaemia medication
UPDATE akt_questions SET explanation = 'ACE inhibitors (e.g. ramipril, enalapril) and ARBs commonly cause hyperkalaemia by reducing aldosterone production, which normally promotes potassium excretion. Risk is particularly high in CKD, diabetes, heart failure, and when combined with potassium-sparing diuretics (spironolactone) or potassium supplements. Monitor U&Es 1–2 weeks after starting/dose change. Amlodipine (calcium channel blocker), metformin, atorvastatin, and paracetamol do not typically cause hyperkalaemia. Other drugs causing hyperkalaemia: trimethoprim, NSAIDs, ciclosporin, and heparin.', updated_at = now() WHERE id = 'd1321d58-cfc7-4c87-9f29-62dea854dd63';

-- Mental Health: Sertraline sexual side effects
UPDATE akt_questions SET explanation = 'If depression is well-controlled on sertraline but sexual side effects persist (reduced libido, anorgasmia, erectile dysfunction — common with SSRIs), consider switching to an antidepressant with lower sexual side effect profile. Options: mirtazapine (noradrenergic, minimal sexual effects), bupropion (not widely available as antidepressant in UK), or vortioxetine. Discuss risks of switching (relapse, withdrawal, new side effects) vs benefits. Do not abruptly stop sertraline — cross-taper. Review after 4–6 weeks on new medication.', updated_at = now() WHERE id = '790baf66-715a-4560-a095-3b35770c2726';

-- Mental Health: Severe depression symptom
UPDATE akt_questions SET explanation = 'Suicidal ideation indicates severe depression and requires urgent risk assessment: current intent, plan, means, hopelessness, protective factors (NICE CG90/NG222). PHQ-9 question 9 asks specifically about self-harm/suicidal thoughts. For severe depression (PHQ-9 ≥20 or suicidal ideation), offer combined SSRI and psychological therapy, and consider referral to crisis team if immediate risk. Poor sleep, low mood, reduced appetite, and fatigue are common depressive symptoms but individually do not indicate severity — assess using validated tools and clinical judgement.', updated_at = now() WHERE id = '03b517cd-b951-4352-9dc2-49ebad58b4ed';

-- Mental Health: First-line SSRI
UPDATE akt_questions SET explanation = 'Sertraline is commonly recommended as first-line SSRI for depression due to its good efficacy, tolerability, and favourable side-effect profile (NICE NG222). It has the most evidence in cardiac patients. Fluoxetine is also widely used first-line (long half-life, fewer withdrawal effects). Citalopram is another common choice but has QTc prolongation risk at higher doses. Paroxetine has more withdrawal effects and is generally avoided. Venlafaxine is an SNRI (not SSRI) used as second-line when SSRIs fail. Start at low dose and titrate.', updated_at = now() WHERE id = 'dd7e54a5-3320-4bde-9b19-f27dd9ee3d09';

-----------------------------------------------------------
-- PART 5: PCOM AND REMAINING SHORT EXPLANATIONS
-----------------------------------------------------------

-- PCOM: GMS contract
UPDATE akt_questions SET explanation = 'GMS (General Medical Services) is the core national contract type in England, used by the majority of GP practices. It is negotiated nationally between NHS England and the BMA GPC. PMS (Personal Medical Services) contracts are locally negotiated and offer flexibility. APMS (Alternative Provider Medical Services) contracts allow non-traditional providers (e.g. private companies) to provide primary care. GMS covers core primary care services and is the standard against which other contracts are measured.', updated_at = now() WHERE id = '89491ee4-65ba-49ae-95a9-ab7acc66793f';

-- PCOM: GP contracts (duplicate)
UPDATE akt_questions SET explanation = 'GMS (General Medical Services) is the core NHS contract type for GP practices in England, negotiated nationally. It provides a Global Sum payment based on practice list size and demographics. PMS (Personal Medical Services) is a locally negotiated alternative. APMS (Alternative Provider Medical Services) allows non-GP providers to hold contracts. Private and local are not standard NHS contract types. Most practices operate under GMS or PMS. The Carr-Hill formula determines Global Sum allocation.', updated_at = now() WHERE id = '526f7d6c-5f8f-48dc-98ba-2926a1015f41';

-- PCOM: Significant events
UPDATE akt_questions SET explanation = 'Significant Event Analysis (SEA) is primarily for learning and improving systems, not for blame or punishment. It involves a structured review of events that could have or did lead to patient harm, using root cause analysis to identify system failures. Documentation of SEAs is required for appraisal and revalidation. The process: identify the event, gather facts, discuss in the team, identify learning points, and implement changes. SEAs are a requirement of the CQC inspection framework and demonstrate a learning culture.', updated_at = now() WHERE id = 'd6d17bc6-a66d-40a5-9290-6d90035c9946';

-- PCOM: GMC core principle
UPDATE akt_questions SET explanation = 'GMC Good Medical Practice (2024) core principle is to make the care of your patient your first concern. Four domains: knowledge skills and performance, safety and quality, communication partnership and teamwork, maintaining trust. Patient safety underpins all medical practice. The four duties: make patient care your first concern, practise medicine safely, maintain professional standards, and be honest and trustworthy. Profit, research, and autonomy, while relevant considerations, are not the core principle.', updated_at = now() WHERE id = 'd021b1ae-b644-4d84-b43a-53b42092990b';

-- PCOM: Social media
UPDATE akt_questions SET explanation = 'GMC guidance on social media: maintain clear boundaries between personal and professional online activity. Never post identifiable patient information. Be aware that patients may search for you online. Comments may be viewed by patients, colleagues, and employers. Do not befriend or follow patients. Report concerns through proper channels, not social media. Assume anonymity is never guaranteed. Posts can be screenshotted and shared. Professional standards apply online as they do offline.', updated_at = now() WHERE id = '103ad7d0-975d-48a3-ab74-8c6bb493d915';

-- PCOM: Appraisal purpose
UPDATE akt_questions SET explanation = 'Medical appraisal is a formative, supportive process focused on professional development, reflection, and identifying learning needs. It is not a performance review, pay review, or disciplinary tool. Annual appraisal is required for revalidation (every 5 years). The appraiser reviews: CPD, quality improvement activities, significant events, complaints, feedback, and professional development plan. Output: agreed personal development plan (PDP) for the coming year. Appraisal should be a safe space for honest reflection.', updated_at = now() WHERE id = '5ab759aa-29d9-440e-9674-799952bae5b1';

-- PCOM: GP trainee supervision
UPDATE akt_questions SET explanation = 'GP trainees are supervised by an Educational Supervisor (ES), who is a trained GP within the practice. The ES oversees the trainee''s educational progress, portfolio review, and workplace-based assessments. Clinical Supervisors (CS) provide day-to-day clinical supervision during placements. The practice manager handles administrative matters but does not provide clinical supervision. CQC regulates the practice but does not supervise trainees. The GMC sets standards but does not directly supervise. Training Programme Directors oversee the programme.', updated_at = now() WHERE id = 'd5be2dee-2409-4e3b-8b70-aa7269203a4e';

-- PCOM: CQC domains
UPDATE akt_questions SET explanation = 'CQC (Care Quality Commission) inspects against five domains: Safe (protecting from abuse/harm), Effective (evidence-based care achieving good outcomes), Caring (treating with compassion, dignity, respect), Responsive (meeting people''s needs), and Well-led (good leadership, governance, culture). Each domain is rated: Outstanding, Good, Requires Improvement, or Inadequate. "Profitable" is not a CQC domain — financial performance is not assessed by CQC. Practices must demonstrate continuous quality improvement.', updated_at = now() WHERE id = '0568a6de-2675-4bc5-a5b0-a72ad6ce08d8';

-- PCOM: Revalidation frequency
UPDATE akt_questions SET explanation = 'Medical revalidation is required every 5 years to maintain GMC registration and licence to practise. It requires satisfactory completion of annual appraisals (usually 5) during the revalidation cycle, plus evidence of: CPD, quality improvement, significant events, feedback from colleagues and patients, complaints review, and health declaration. The Responsible Officer makes the revalidation recommendation to the GMC. Failure to engage with revalidation can result in loss of licence to practise.', updated_at = now() WHERE id = '22b6824d-438f-4624-bc62-95d537fa6740';

-- PCOM: Communication failures
UPDATE akt_questions SET explanation = 'Communication failures are the most common cause of medicolegal claims, complaints, and patient safety incidents in primary care. Examples: failure to communicate test results, inadequate safety-netting, unclear referral letters, poor handover, and misunderstandings during consultations. Improving communication: use structured communication tools (SBAR), read-back for critical information, document clearly, safety-net with specific instructions, and ensure patients understand their management plan. Good communication reduces litigation risk more than perfect clinical care.', updated_at = now() WHERE id = 'dffda3d7-c9d9-43d1-a785-d97b95b02bee';

-- PCOM: Smoking cessation (stem rewrite already done, ensure explanation is okay — already updated above)

-- PCOM: Death certification
UPDATE akt_questions SET explanation = 'The MCCD (Medical Certificate of Cause of Death) is completed by the attending doctor — the registered medical practitioner who attended the deceased during their last illness. The doctor must have seen the patient within 28 days before death (or examined the body after death). "Any doctor" or the coroner do not routinely complete MCCDs. The registrar registers the death based on the MCCD. Nurses cannot issue MCCDs. If the cause of death is unknown, unnatural, or the doctor did not attend in the last illness, the death should be referred to the coroner.', updated_at = now() WHERE id = '5b9a6e59-90c0-4c16-8674-6b2eb15e1783';

-- PCOM: AI governance
UPDATE akt_questions SET explanation = 'AI acceptable use in healthcare requires clinician oversight at all times — AI can assist clinical decision-making but must not replace it. The clinician remains responsible and accountable for all decisions. AI tools must not be used to diagnose independently, make treatment decisions without review, enter identifiable patient data into non-approved tools, or used without transparency (patients should be informed). AI outputs must be critically appraised, documented, and verified. Data governance (GDPR compliance) is essential. Follow local trust/practice AI policies.', updated_at = now() WHERE id = '6e49ed27-3c27-4378-bef1-3d1e08e85244';

-- PCOM: Consent
UPDATE akt_questions SET explanation = 'Consent can be withdrawn at any time, even during a procedure — this is a fundamental principle. Verbal consent is valid for many procedures (examination, blood tests); written consent is recommended for significant procedures (surgery, invasive investigations). Capacity is not permanent — it is decision-specific and can fluctuate (Mental Capacity Act 2005). Implied consent is valid for routine examinations (e.g. patient rolls up sleeve for BP). Children under 16 can consent if Gillick-competent. Consent must be informed: explain risks, benefits, alternatives, and consequences of refusal.', updated_at = now() WHERE id = 'ca5b651b-f1c3-48e6-988d-2860ef0a313f';

-- PCOM: Gift acceptance
UPDATE akt_questions SET explanation = 'Professional boundaries around gifts: small tokens of appreciation (e.g. box of chocolates, thank-you card) are generally acceptable but should be shared with the team. Larger gifts (cash, expensive items) should be declined as they may create a sense of obligation. Never solicit gifts or accept gifts that could influence care. Follow practice policy on gift acceptance. Consider the context (vulnerable patients, ongoing treatment decisions). Document if concerned. GMC Good Medical Practice advises maintaining clear boundaries.', updated_at = now() WHERE id = 'c9506f32-501c-414a-88d2-2fa795626c5f';

-- PCOM: Whistleblowing
UPDATE akt_questions SET explanation = 'Whistleblowing (raising concerns) guidance encourages speaking up through proper channels when patient safety is at risk. GMC duty: you must raise concerns if you believe patients are at risk. First step: raise with line manager or responsible person. If unresolved: Freedom to Speak Up Guardian, medical director, or external bodies (CQC, GMC, NHS England). External media or social media should only be used as an absolute last resort after all internal channels have been exhausted. Whistleblowers are protected by law (Public Interest Disclosure Act 1998).', updated_at = now() WHERE id = 'eae35d3a-1c09-4f3f-9106-04993ccc4032';

-- PCOM: Health inequalities
UPDATE akt_questions SET explanation = 'GPs have a role in reducing health inequalities through: advocacy for patients facing barriers to care, improving access (e.g. flexible appointments, interpreters, accessible premises), targeted screening and health promotion in deprived populations, addressing social determinants of health (housing, employment, education), and working with public health and community organisations. "Inverse care law" (Tudor Hart): those most in need receive least care. This is not just about clinical care — it requires system-level engagement and population health thinking.', updated_at = now() WHERE id = '3830142c-bb66-4e1b-9ca6-0dcaea004695';

-- PCOM: Leadership
UPDATE akt_questions SET explanation = 'Effective leadership requires emotional intelligence — understanding and managing your own emotions, empathising with others, building relationships, and navigating conflict constructively. This is more important than positional authority, speed, or hierarchy. Key leadership competencies in primary care: communication, team-building, change management, clinical governance, and strategic thinking. GP leaders should model professional behaviour, support team development, and create a culture of safety and learning. The NHS Healthcare Leadership Model outlines nine leadership dimensions.', updated_at = now() WHERE id = '2b990c67-5a90-4a74-b307-0ebe1eac8dd0';

-- PCOM: Resilience
UPDATE akt_questions SET explanation = 'Resilience is most effectively built through reflection, peer support networks, maintaining work-life boundaries, and regular debriefing. Working longer hours, social isolation, avoidance of difficult situations, and perfectionism actually reduce resilience and increase burnout risk. Practical strategies: Schwartz rounds, Balint groups, peer support, supervision, regular exercise, hobbies outside medicine, and mindfulness. Systemic factors matter too — organisational support, manageable workload, and autonomy are protective. Resilience is not just individual responsibility; it requires supportive systems.', updated_at = now() WHERE id = '5fb1c94c-c7ae-49f2-83fc-4c32b9959a9b';

-- PCOM: Practice income
UPDATE akt_questions SET explanation = 'Practice income primarily comes from the Global Sum — core funding calculated using the Carr-Hill formula based on list size, demographics, rurality, and deprivation. Enhanced services (DES/LES) are optional commissioned services providing additional income (e.g. minor surgery, vaccination programmes, extended hours). QOF (Quality and Outcomes Framework) provides performance-related payments based on clinical and organisational quality indicators. Other income: private work (insurance reports, medicals), rent reimbursement, and PCN (Primary Care Network) funding.', updated_at = now() WHERE id = 'c16d0c06-4d17-4b6d-95c1-e7c5f9431e26';

-- PCOM: Appraisal primarily supports
UPDATE akt_questions SET explanation = 'Appraisal primarily supports reflection and professional development. While it is required for revalidation (GMC requirement), its main purpose is to help doctors reflect honestly on their practice, identify learning needs, set development goals, and improve patient care. It is formative (developmental) not summative (pass/fail). Key elements: reflecting on significant events, reviewing patient and colleague feedback, discussing CPD activities, and creating a personal development plan (PDP). The appraiser''s role is to facilitate this reflective process, not to judge performance.', updated_at = now() WHERE id = 'dc0fc878-2003-4aea-b29a-1ed61678ef3a';

-- PCOM: Total triage
UPDATE akt_questions SET explanation = 'Total triage aims to match patient demand to capacity safely by ensuring all patient requests are assessed and directed to the most appropriate service (GP, nurse, pharmacist, self-care, A&E). It is designed to improve access and efficiency, not to reduce appointments or ration care. Patients contact the practice (phone, online), their request is triaged (by trained staff or clinician), and they are directed to the most appropriate response (same-day, routine, advice, redirect). Risks include: missed red flags in non-face-to-face triage, digital exclusion, and increased administrative burden.', updated_at = now() WHERE id = '9092cc40-5ffc-4f0e-9c2f-00d999148c67';

-- PCOM: Online consultation risks
UPDATE akt_questions SET explanation = 'Online consultation risks include missed red flags due to inability to see the patient (no physical examination, limited non-verbal cues), digital exclusion (elderly, non-English speakers, learning disabilities), data security concerns, and potential for increased workload if not managed well. Good practice: structured questionnaires with red flag prompts, clear documentation of clinical reasoning, robust safety-netting, and ensuring accessible alternatives for patients who cannot use digital tools. Documentation must include differentials considered and red flags excluded.', updated_at = now() WHERE id = 'ecf4b170-3aa0-4215-b28c-65ca936b2f8c';

-- PCOM: Capacity assessment
UPDATE akt_questions SET explanation = 'Mental Capacity Act 2005: capacity requires the ability to (1) understand the information relevant to the decision, (2) retain that information long enough to make the decision, (3) weigh up (use) the information to make the decision, and (4) communicate the decision. Capacity is decision-specific and time-specific. A patient may have capacity for one decision but not another. Agreement with the doctor is not required — patients have the right to make "unwise" decisions. Family members cannot make decisions unless they hold a lasting power of attorney.', updated_at = now() WHERE id = '51446a8f-dd69-4db3-a8e3-1f4a1da360a3';

-- PCOM: Fluctuating capacity
UPDATE akt_questions SET explanation = 'Fluctuating capacity (e.g. in delirium, dementia with lucid intervals, psychosis) requires assessment at each decision point. Do not assume a patient lacks capacity just because they sometimes lack it. If possible, time the assessment to when the patient is most likely to have capacity. Document the assessment clearly. Family members do not make decisions (unless holding LPA). Court of Protection is a last resort for complex cases. Best interests decisions apply when capacity is absent, involving consultation with family and relevant professionals.', updated_at = now() WHERE id = 'af698a4e-3332-47f8-bdba-14e100377b9e';

-- PCOM: Fitness to drive advisor
UPDATE akt_questions SET explanation = 'The GP advises the patient about fitness to drive and the legal requirement to inform DVLA of relevant medical conditions (e.g. epilepsy, diabetes on insulin, visual impairment, cognitive impairment). If the patient refuses to notify DVLA and continues to drive, the GP may need to breach confidentiality and inform DVLA directly (GMC guidance). Occupational health assesses fitness for specific occupational driving roles. The DVLA makes the final licensing decision. Police enforce road traffic law but do not assess medical fitness.', updated_at = now() WHERE id = 'bd259d8e-c8cc-4247-9cb2-b36f81fd55f3';

-- PCOM: QOF purpose
UPDATE akt_questions SET explanation = 'QOF (Quality and Outcomes Framework) incentivises evidence-based primary care quality through payment for achieving clinical and organisational indicators. Clinical indicators cover chronic disease management (diabetes, hypertension, asthma, COPD, mental health). It is a voluntary pay-for-performance scheme. QOF does not focus on private care, hospital activity, or research output. Points are converted to payment based on practice list size. Criticisms include: gaming, focus on measurable over meaningful outcomes, and administrative burden. QOF undergoes regular revision.', updated_at = now() WHERE id = '950abcb8-3cc1-418b-8963-c8a62cb5f2a9';

-- PCOM: Complaints first step
UPDATE akt_questions SET explanation = 'The first step in managing a complaint is to acknowledge it promptly (within 3 working days) and investigate the facts. Express empathy and take the concern seriously. Key principles: listen, acknowledge, investigate thoroughly, respond in writing with findings and actions taken, and learn from the complaint. Being defensive, ignoring, or threatening legal action worsens the situation and increases risk of escalation to the Parliamentary and Health Service Ombudsman. Use the opportunity for quality improvement. Document the process and outcome.', updated_at = now() WHERE id = 'f8a8aedb-9bde-4183-82c3-1c5b624c34da';

-- PCOM: Medicolegal defence
UPDATE akt_questions SET explanation = 'Clear documentation of clinical reasoning (differentials considered, red flags excluded, rationale for management), safety-netting (specific instructions on when to return, what to watch for), and follow-up plans significantly improves medicolegal defence. "If it wasn''t documented, it wasn''t done" is the medicolegal standard. Minimal notes, copy-paste templates without personalisation, and failure to safety-net are common litigation triggers. Document what you thought, what you did, and what you told the patient.', updated_at = now() WHERE id = 'ce470fb7-a9e3-454e-a8db-7e601c3750a0';

-- PCOM: AI acceptable use
UPDATE akt_questions SET explanation = 'Drafting letters, summaries, or documents using AI that are then reviewed, checked, and edited by a clinician is acceptable use. Unacceptable: entering identifiable patient data into non-approved/public AI tools (GDPR breach), delegating clinical decisions to AI without review, using AI outputs without verification, or failing to disclose AI use when relevant. The clinician remains accountable for all outputs. AI should enhance, not replace, clinical judgement. Follow local governance policies and document AI-assisted processes.', updated_at = now() WHERE id = '597bf01c-62f6-465e-b4b3-4e1bc59f7642';

-- PCOM: Total triage (duplicate)
UPDATE akt_questions SET explanation = 'Total triage aims to direct every patient request to the most appropriate skill level (GP, ANP, nurse, pharmacist, self-care), improving efficiency and access while maintaining safety. It does not aim to reduce GP appointments, increase workload on reception, or eliminate face-to-face consultations. Key principles: every contact is assessed, patients are directed to the right person at the right time, safety-netting is clear, and digitally excluded patients have alternative access routes. Requires robust protocols, training, and regular audit.', updated_at = now() WHERE id = 'c86a2039-05db-4fc3-96a2-212c32404431';

-- PCOM: Trainees attend practice meetings
UPDATE akt_questions SET explanation = 'GP trainees should attend practice meetings to understand practice systems, leadership, governance, and the business of general practice — not just clinical work. Practice meetings cover significant events, complaints, QOF performance, finance, CQC preparation, and service development. This prepares trainees for future roles as partners or salaried GPs. It also helps trainees understand how clinical decisions have organisational and financial implications. Engagement demonstrates professionalism and interest in the wider practice.', updated_at = now() WHERE id = 'e3cf7a70-9305-4e03-81ca-b20d86c55b41';

-- PCOM: GP partner skills
UPDATE akt_questions SET explanation = 'Conflict management is a crucial skill for GP partners who must navigate complex team dynamics, patient complaints, partnership disagreements, and practice challenges. Other essential partner skills include: financial management, strategic planning, HR management, governance, and leadership. Exam scores, research output, and clinical speed, while valuable, are less central to the daily reality of partnership. Partnership is a business role as much as a clinical one, requiring management competencies alongside clinical excellence.', updated_at = now() WHERE id = 'c4e8678c-ea73-480a-8cd1-b6de834238cf';

-- PCOM: Burnout prevention
UPDATE akt_questions SET explanation = 'Setting boundaries (work-life balance, saying no, manageable workload) and regular debriefing (peer support, Schwartz rounds, Balint groups) are key strategies for preventing burnout. Longer clinics, ignoring administrative duties, and working in isolation increase burnout risk. Other protective factors: maintaining hobbies and relationships outside medicine, regular exercise, adequate sleep, and accessing occupational health support when needed. Burnout is not solely an individual responsibility — systemic factors (workload, staffing, support) play a major role.', updated_at = now() WHERE id = 'd1e30085-d68c-4638-822f-32067d27b155';

-- PCOM: Disclosure for safety-critical work
UPDATE akt_questions SET explanation = 'Epilepsy must be disclosed for safety-critical work (e.g. driving, operating heavy machinery, piloting) as seizures can cause harm to the individual and others. Driving restrictions: must be seizure-free for 12 months (car/motorcycle) or 5 years (HGV/bus). Other conditions requiring disclosure depend on the role: insulin-treated diabetes (driving restrictions apply), visual impairment, cardiac conditions affecting consciousness. The duty to disclose is the individual''s, but occupational health advises on fitness for the specific role.', updated_at = now() WHERE id = 'd4265074-95c5-4a94-a25c-7a0430ae04e6';

-- PCOM: Fitness for work
UPDATE akt_questions SET explanation = 'Fitness for work is assessed by occupational health (OH), not the GP. The GP provides medical information (fit notes, medical reports) but does not make the fitness-for-work decision, which depends on job-specific requirements. OH assesses whether the individual can perform their role safely, recommends adjustments (under the Equality Act 2010), and advises on return-to-work plans. The employer makes the final management decision based on OH advice. Police, GMC, and CQC do not assess fitness for work.', updated_at = now() WHERE id = 'da78e81a-71f2-4b8b-bb68-5d5d193e9ba1';

-- PCOM: Sexual assault
UPDATE akt_questions SET explanation = 'Sexual assault management: offer immediate referral to a Sexual Assault Referral Centre (SARC), which provides forensic examination, emergency contraception, PEP (post-exposure prophylaxis for HIV if appropriate), STI screening, and psychological support. Evidence does not expire at 24 hours — forensic evidence can be collected up to 7 days. Reporting to police is the patient''s choice (not mandatory for adults). Document sensitively using the patient''s own words. Never examine without consent. Offer follow-up and safeguarding assessment if children are involved.', updated_at = now() WHERE id = 'e4eaf09c-c07e-48b3-8d4c-6c896403f16e';

-- PCOM: Safeguarding adults
UPDATE akt_questions SET explanation = 'Safeguarding adults concerns can be raised by any professional who identifies risk of abuse, neglect, or self-neglect — GP, nurse, social worker, police, family member, or the individual themselves. The Care Act 2014 defines safeguarding responsibilities. Types of abuse: physical, sexual, emotional, financial, neglect, organisational, discriminatory, modern slavery. Concerns should be raised with local adult safeguarding team. GPs play a key role in identifying abuse through consultation patterns, injuries, and changes in behaviour.', updated_at = now() WHERE id = 'e4e61b63-9e15-4989-a63b-a800c37b0afc';

-- PCOM: Exam mindset
UPDATE akt_questions SET explanation = 'Best exam mindset: trust your preparation, stay calm, and work methodically through questions. Attempting to memorise everything at the last minute increases anxiety and reduces performance. Repeated answer-changing usually decreases scores — stick with your first instinct unless clearly wrong. Over-revising the night before impairs sleep and next-day performance. Time management is key: pace yourself, mark uncertain questions for review, and don''t spend too long on any single question. Eat well, sleep well, and arrive early.', updated_at = now() WHERE id = 'ffb57e05-8d17-404a-a883-f6cf228e4929';

-- PCOM: Coroner referral
UPDATE akt_questions SET explanation = 'Deaths that must be referred to the coroner: sudden/unexplained death, cause of death unknown, death within 24 hours of hospital admission, death during or shortly after surgery/anaesthesia, death related to industrial disease, death in custody/detention, death related to neglect or violence, and deaths where the doctor did not attend during the last illness or cannot issue a MCCD. Expected deaths from known conditions (e.g. palliative cancer, known terminal illness with DNACPR) do not require referral if the cause is clear and the doctor can certify.', updated_at = now() WHERE id = '5d4f34c6-05c6-4ff3-ae02-77fedf821cd3';

-- PCOM: Online consultation documentation
UPDATE akt_questions SET explanation = 'In online/remote consultations, documenting differential diagnosis and safety-netting is essential — just as in face-to-face consultations. Because you cannot examine the patient, it is even more important to: document what differentials you considered, what red flags you asked about and excluded, what you advised the patient to do if symptoms worsen, and when to seek further help. Template-only documentation without clinical reasoning is insufficient and medicolegally risky. Clear safety-netting instructions should be specific, not generic.', updated_at = now() WHERE id = '1595b2fb-8a50-4a96-833a-8903c56b2321';

-- PCOM: Domestic abuse
UPDATE akt_questions SET explanation = 'Domestic abuse: document using the patient''s own words (verbatim in quotation marks). Never ask about domestic abuse when the partner is present — create a safe, private opportunity. Do not advise the patient to confront their partner (increases danger). You cannot promise absolute confidentiality if there are safeguarding concerns (children, vulnerable adults at risk). Offer referral to specialist domestic abuse services (local IDVA/ISVA, National Domestic Abuse Helpline). Complete a risk assessment (DASH-RIC) and follow local safeguarding pathways.', updated_at = now() WHERE id = '7a138ada-4596-4c29-afdb-4cca9a4ae694';

-- PCOM: Medicolegal risk
UPDATE akt_questions SET explanation = 'Communication failure is the most common medicolegal risk in general practice. Most complaints and negligence claims arise from breakdowns in communication — failure to explain diagnosis or management clearly, inadequate safety-netting, poor documentation of clinical reasoning, miscommunication between professionals (handover, referral), and failure to communicate test results. Good communication (clear language, checking understanding, written information, safety-netting, timely follow-up) is the most effective risk reduction strategy.', updated_at = now() WHERE id = '845a4b36-a5e1-4e58-9864-01d70bfcc79c';

-- PCOM: AI documentation
UPDATE akt_questions SET explanation = 'AI documentation best practice: clinician must review, verify, and edit all AI-generated content before it becomes part of the patient record. Never copy AI output blindly into notes without review — errors, hallucinations, and inappropriate content can occur. Obtain patient consent or at minimum disclose AI use. Maintain a record of AI-assisted processes. Never delete original clinical notes in favour of AI-generated summaries. The clinician remains accountable for the accuracy and appropriateness of all documentation.', updated_at = now() WHERE id = 'c45fb117-8414-4ee1-97ad-df4135ea4409';

-- PCOM: Data security
UPDATE akt_questions SET explanation = 'Patient data must be stored securely according to GDPR (General Data Protection Regulation) and the Data Protection Act 2018. Data should never be shared freely, emailed unencrypted, made publicly accessible, or treated as optional. Access should be on a need-to-know basis with appropriate role-based permissions. Data processing requires a lawful basis. Patient-identifiable data should not be entered into public AI tools or shared via insecure channels. Data breaches must be reported to the ICO (Information Commissioner''s Office) within 72 hours.', updated_at = now() WHERE id = '53913e6b-5a7a-48e0-99ac-e6ec19297df2';

-- PCOM: Safeguarding red flag
UPDATE akt_questions SET explanation = 'Inconsistent injury history (the explanation of how an injury occurred doesn''t match the injury pattern, changes on retelling, or is developmentally implausible) is a red flag for non-accidental injury and should prompt safeguarding referral. Other red flags: delay in presenting, multiple injuries at different stages of healing, injuries in non-mobile infants, unusual injury patterns, and a child who is withdrawn or fearful. Missed immunisations, common viral illness, and occasional school absence, while worth noting, are not specific safeguarding red flags in isolation.', updated_at = now() WHERE id = '5f9018bd-efc6-48e7-969f-8759641fc2a2';
